附录C：完整启动链配置示例（i.MX6Q + eMMC） <pre><code># === 1. U-Boot配置文件 ===
# configs/imx6q_custom_defconfig

CONFIG_ARM=y
CONFIG_ARCH_MX6=y
CONFIG_TARGET_MX6Q_CUSTOM=y
CONFIG_SPL=y
CONFIG_SPL_MMC_SUPPORT=y
CONFIG_SPL_SERIAL_SUPPORT=y
CONFIG_SPL_GPIO_SUPPORT=y
CONFIG_SPL_LIBCOMMON_SUPPORT=y
CONFIG_SPL_LIBGENERIC_SUPPORT=y
CONFIG_HUSH_PARSER=y
CONFIG_CMD_BOOTZ=y
CONFIG_CMD_MMC=y
CONFIG_CMD_FAT=y
CONFIG_CMD_EXT4=y
CONFIG_CMD_I2C=y
CONFIG_CMD_USB=y
CONFIG_CMD_DHCP=y
CONFIG_CMD_PING=y
CONFIG_CMD_CACHE=y
CONFIG_CMD_REGULATOR=y
CONFIG_OF_CONTROL=y
CONFIG_ENV_IS_IN_MMC=y
CONFIG_ENV_OFFSET=0xC0000
CONFIG_ENV_SIZE=0x20000
CONFIG_DM_MMC=y
CONFIG_DM_ETH=y
CONFIG_FEC_MXC=y
CONFIG_PHYLIB=y
CONFIG_USB=y
CONFIG_DM_USB=y
CONFIG_USB_STORAGE=y
CONFIG_USB_HOST_ETHER=y
CONFIG_USB_ETHER_ASIX=y

# === 2. 内核配置 ===
# arch/arm/configs/imx6_custom_defconfig

CONFIG_ARCH_MX6=y
CONFIG_SOC_IMX6Q=y
CONFIG_SMP=y
CONFIG_ARM_PSCI=y
CONFIG_HIGHMEM=y
CONFIG_CMA=y
CONFIG_CMA_SIZE_MBYTES=64

# 存储驱动（必须=y，不能=m）
CONFIG_MMC=y
CONFIG_MMC_BLOCK=y
CONFIG_MMC_SDHCI=y
CONFIG_MMC_SDHCI_PLTFM=y
CONFIG_MMC_SDHCI_ESDHC_IMX=y

# 文件系统（必须=y）
CONFIG_EXT4_FS=y
CONFIG_EXT4_USE_FOR_EXT2=y
CONFIG_VFAT_FS=y
CONFIG_TMPFS=y
CONFIG_DEVTMPFS=y
CONFIG_DEVTMPFS_MOUNT=y

# 网络（必须=y）
CONFIG_FEC=y
CONFIG_PHYLIB=y
CONFIG_MICREL_PHY=y

# 串口（必须=y）
CONFIG_SERIAL_IMX=y
CONFIG_SERIAL_IMX_CONSOLE=y
CONFIG_CONSOLE_TRANSLATIONS=y

# === 3. 设备树片段 ===
# arch/arm/boot/dts/imx6q-custom.dts

/ {
    model = "Custom i.MX6Q Board";
    compatible = "custom,imx6q-custom", "fsl,imx6q";

    chosen {
        stdout-path = &amp;uart1;
        bootargs = "console=ttymxc0,115200 rw root=/dev/mmcblk0p2 rootwait";
    };

    memory@10000000 {
        device_type = "memory";
        reg = &lt;0x10000000 0x40000000&gt;; /* 1GB DDR */
    };
};

&amp;usdhc1 {
    pinctrl-names = "default";
    pinctrl-0 = &lt;&amp;pinctrl_usdhc1&gt;;
    bus-width = &lt;8&gt;;
    non-removable;
    no-1-8-v;
    status = "okay";
};

&amp;uart1 {
    pinctrl-names = "default";
    pinctrl-0 = &lt;&amp;pinctrl_uart1&gt;;
    status = "okay";
};

&amp;fec {
    pinctrl-names = "default";
    pinctrl-0 = &lt;&amp;pinctrl_enet&gt;;
    phy-mode = "rgmii";
    phy-handle = &lt;&amp;eth_phy&gt;;
    status = "okay";

    mdio {
        eth_phy: ethernet-phy@1 {
            compatible = "ethernet-phy-ieee802.3-c22";
            reg = &lt;1&gt;;
        };
    };
};

# === 4. 分区表 ===
# parted /dev/mmcblk0

Number  Start   End     Size    File system  Name     Flags
 1      1MB     65MB    64MB    fat16        boot     msftdata
 2      65MB    1025MB  960MB   ext4         rootfs
 3      1025MB  7265MB  6240MB  ext4         data

# boot分区: kernel(zImage/Image) + DTB + boot.scr
# rootfs分区: 完整的Linux rootfs
# data分区: 用户数据和配置

# === 5. U-Boot环境变量 ===
# uEnv.txt (FAT分区中的U-Boot脚本)

bootargs=console=${console} ${optargs} root=${mmcroot} rootfstype=${mmcrootfstype} ${cmdline}
console=ttymxc0,115200n8
mmcroot=/dev/mmcblk0p2 rw
mmcrootfstype=ext4 rootwait
optargs=initcall_debug quiet

loadaddr=0x80800000
fdtaddr=0x83000000

loadkernel=ext4load mmc 0:2 ${loadaddr} /boot/zImage
loaddtb=ext4load mmc 0:2 ${fdtaddr} /boot/${soc}-${board}.dtb

bootcmd=run findfdt; run loadkernel; run loaddtb; bootz ${loadaddr} - ${fdtaddr}
</code></pre>   <p>💡 提示: 启动链的理解是嵌入式Linux工程师的核心能力。建议你在自己的产品上做一次完整的启动日志分析——从U-Boot第一行输出到systemd最后一个服务启动——逐行记录时间戳，画出时间线，找出最大的三个耗时点。这个练习会让你对产品的启动行为有深入的理解，也能让你在启动问题发生时快速定位。</p> <p>🔴 危险: 生产设备的Secure Boot一旦启用（eFUSE烧录），是不可逆的。如果签名密钥丢失或SPL签名错误，设备将永久变砖（无法通过Serial Download恢复，因为Secure Boot会拒绝未签名的代码）。务必在生产前建立完整的密钥管理流程，保留备份密钥，并在小批量上充分验证。</p>   <p>文档完成 | 目标字数: 18,000-22,000字 | 实际字数: ~20,000字 | 知识点: 393 [E] </p>

