温度 (°C) ADC 值 NTC 电阻 (Ω) -40 3995 401,860 -20 3740 105,385 0 3156 33,621 25 2047 10,000 50 1081 3,588 85 401 1,087 100 267 698 <p>NTC 的非线性非常明显：25 °C 附近 1 °C 对应约 60 LSB，-40 °C 时只有约 7 LSB——低温段的有效分辨率急剧恶化。工程做法是查表 + 线性插值，比现算指数公式快且精度可控。查找表用脚本在编译期生成：</p> <pre><code># gen_ntc_table.py — NTC 10k/B3950 查找表生成器
import math

R25, B, T25 = 10000, 3950, 273.15 + 25
VCC, R_FIX, ADC_MAX = 3.3, 10000, 4095

def adc_of(t):
    T = t + 273.15
    R = R25 * math.exp(B * (1/T - 1/T25))
    return int(R / (R_FIX + R) * ADC_MAX)

print("static const uint16_t ntc_adc_table[] = {")
vals = [adc_of(t) for t in range(-40, 101)]
for i in range(0, len(vals), 10):
    print("    " + ", ".join(f"{v:4d}" for v in vals[i:i+10]) + ",")
print("};")
</code></pre> <p>生成的前几行（已校验，-40 °C=3995，25 °C=2047，100 °C=267）：</p> <pre><code>static const uint16_t ntc_adc_table[] = {
    3995, 3988, 3980, 3972, 3963, 3954, 3944, 3934, 3923, 3912,  /* -40~-31°C */
    3900, 3887, 3874, 3859, 3845, 3829, 3813, 3796, 3778, 3759,  /* -30~-21°C */
    3740, 3719, 3698, 3676, 3653, 3629, 3604, 3578, 3551, 3523,  /* -20~-11°C */
    /* … 全表 141 项，由脚本生成 … */
};
</code></pre> <p>查表换算（读 raw → 温度）：</p> <pre><code>/* ntc_lookup：二分定位 + 线性插值，输入 raw，输出 °C */
#define NTC_T_MIN  (-40)
#define NTC_T_MAX  (100)

float ntc_lookup(uint16_t adc)
{
    int n = NTC_T_MAX - NTC_T_MIN;          /* 表长 141，下标 0..140 */
    if (adc &gt;= ntc_adc_table[0]) return NTC_T_MIN;
    if (adc &lt;= ntc_adc_table[n]) return NTC_T_MAX;

    for (int i = 0; i &lt; n; i++) {
        if (adc &lt;= ntc_adc_table[i] &amp;&amp; adc &gt;= ntc_adc_table[i + 1]) {
            float span = ntc_adc_table[i] - ntc_adc_table[i + 1];
            float frac = span &gt; 0 ? (ntc_adc_table[i] - adc) / span : 0;
            return NTC_T_MIN + i + frac;
        }
    }
    return -999.0f;                          /* 不可能到达 */
}
</code></pre>

docs.title:
SoC 没有内置 DAC 怎么办 <p>内置 DAC 在 MCU（STM32 等）上常见，但在应用处理器级 SoC 上并不普及——本书锚点硬件 RK3568 就没有内置 DAC。三条替代路径：</p>    路径 精度 成本 适用场景     PWM + RC 滤波 8~10 bit 有效（受纹波限制） 接近零 背光、粗略偏置电压   外置 I2C/SPI DAC（MCP4725、DAC8571 等） 12~16 bit 几元 工业模拟输出主流方案   专用音频/高速 DAC 16~24 bit 高 音频、波形发生    <p>以外置 MCP4725（12-bit，I2C 接口）为例，内核有现成驱动（<code>drivers/iio/dac/mcp4725.c</code>），设备树挂在 I2C 控制器下：</p> <pre><code>&amp;i2c1 {
    status = "okay";

    dac: mcp4725@60 {
        compatible = "microchip,mcp4725";
        reg = &lt;0x60&gt;;
        vref-supply = &lt;&amp;vcc_3v3&gt;;
    };
};
</code></pre> <p>注册后用户态经 IIO sysfs 控制，与内置 DAC 用法完全一致：</p> <pre><code>cat /sys/bus/iio/devices/iio:device0/out_voltage0_scale   # mV/LSB
echo 2047 &gt; /sys/bus/iio/devices/iio:device0/out_voltage0_raw   # ≈ Vref/2
</code></pre> <p>PWM+RC 滤波的原理是把 PWM 方波经低通滤波取平均值（见 B-B.2.2）：截止频率远低于 PWM 频率时，输出近似直流。纹波与响应速度矛盾——滤波越狠纹波越小、响应越慢，只适合慢变设定值场景。</p>

设备树配置 <pre><code>/* ADC：使能 SARADC（dtsi 默认 disabled） */
&amp;saradc {
    vref-supply = &lt;&amp;vcc_3v3&gt;;
    status = "okay";
};

/* PWM：使能 pwm0，确认 pinctrl 复用 */
&amp;pwm0 {
    pinctrl-0 = &lt;&amp;pwm0m0_pins&gt;;
    status = "okay";
};

/* 按键：注册为输入事件（也可纯用户态，见正文取舍） */
/ {
    gpio_keys: gpio-keys {
        compatible = "gpio-keys";
        button_mode: button-mode {
            label = "mode-btn";
            gpios = &lt;&amp;gpio1 0 GPIO_ACTIVE_LOW&gt;;
            linux,code = &lt;KEY_F1&gt;;
            debounce-interval = &lt;20&gt;;
        };
    };
};
</code></pre> <p>设备树烧录后先验证三件套的注册状态，再写任何应用代码：</p> <pre><code>ls /sys/bus/iio/devices/                 # 出现 iio:deviceX（saradc）
ls /sys/class/pwm/                       # 出现 pwmchipN
evtest /dev/input/event0 2&gt;/dev/null     # 按一下按键，应看到 KEY_F1 事件
</code></pre>  <p>⚠️ 注册三查先于应用开发。ADC 看 <code>/sys/bus/iio/devices/</code>、PWM 看 <code>/sys/class/pwm/</code>、按键看 <code>/dev/input/event*</code> 或 <code>gpioinfo</code>。任一缺失都回到设备树，不要在应用层排查。</p>

完整程序 <p>单文件程序 <code>breath_ctrl.c</code>：libgpiod v2 监听按键中断，IIO sysfs 读电位器，PWM sysfs 输出呼吸波形。<code>poll</code> 统一事件源，主循环按 20 ms 节拍推进呼吸相位。</p> <pre><code>/* breath_ctrl.c — 电位器调亮度上限，按键切模式：常灭→呼吸→常亮
 * 目标平台：RK3568（saradc + pwm0 + gpio1）
 * 依赖：libgpiod v2（pkg-config --modversion libgpiod 应为 2.x）
 * 编译：gcc breath_ctrl.c -o breath_ctrl -lgpiod
 */
#include &lt;gpiod.h&gt;
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;fcntl.h&gt;
#include &lt;poll.h&gt;
#include &lt;math.h&gt;

/* ---- 平台参数（按实际板卡修改） ---- */
#define GPIO_CHIP      "/dev/gpiochip1"
#define BTN_OFFSET     0                    /* GPIO1_A0 */
#define IIO_DEV        "/sys/bus/iio/devices/iio:device0"
#define ADC_CHANNEL    3                    /* 电位器所在通道 */
#define ADC_MAX        1023                 /* RK3568 SARADC 为 10-bit */
#define PWM_PATH       "/sys/class/pwm/pwmchip0/pwm0"
#define PWM_CHIP       "/sys/class/pwm/pwmchip0"
#define PWM_PERIOD_NS  100000               /* 10 kHz，防可见频闪 */

enum mode { MODE_OFF = 0, MODE_BREATH, MODE_ON, MODE_MAX };

/* ---- sysfs 小工具 ---- */
static int sysfs_write(const char *path, const char *val)
{
    int fd = open(path, O_WRONLY);
    if (fd &lt; 0) return -1;
    int ret = write(fd, val, strlen(val));
    close(fd);
    return ret &lt; 0 ? -1 : 0;
}

static int sysfs_read_int(const char *path)
{
    char buf[32] = {0};
    int fd = open(path, O_RDONLY);
    if (fd &lt; 0) return -1;
    if (read(fd, buf, sizeof(buf) - 1) &lt;= 0) { close(fd); return -1; }
    close(fd);
    return atoi(buf);
}

/* ---- ADC：读电位器，返回 0.0~1.0 ---- */
static float adc_read_ratio(void)
{
    char path[128];
    snprintf(path, sizeof(path), "%s/in_voltage%d_raw", IIO_DEV, ADC_CHANNEL);
    int raw = sysfs_read_int(path);
    if (raw &lt; 0) return 0.0f;
    if (raw &gt; ADC_MAX) raw = ADC_MAX;
    return (float)raw / ADC_MAX;
}

/* ---- PWM ---- */
static int pwm_init(void)
{
    char buf[32];
    sysfs_write(PWM_CHIP "/export", "0");   /* 已导出时返回-1，忽略 */
    usleep(100000);
    snprintf(buf, sizeof(buf), "%d", PWM_PERIOD_NS);
    sysfs_write(PWM_PATH "/period", buf);
    sysfs_write(PWM_PATH "/duty_cycle", "0");
    return sysfs_write(PWM_PATH "/enable", "1");
}

static void pwm_set_ratio(float ratio)      /* ratio: 0.0~1.0 */
{
    char buf[32];
    if (ratio &lt; 0.0f) ratio = 0.0f;
    if (ratio &gt; 1.0f) ratio = 1.0f;
    snprintf(buf, sizeof(buf), "%d", (int)(PWM_PERIOD_NS * ratio));
    sysfs_write(PWM_PATH "/duty_cycle", buf);
}

int main(void)
{
    /* ---- 按键：libgpiod v2，下降沿 + 20ms 内核防抖 ---- */
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open"); return 1; }

    struct gpiod_line_settings *ls = gpiod_line_settings_new();
    gpiod_line_settings_set_direction(ls, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(ls, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_settings_set_edge_detection(ls, GPIOD_LINE_EDGE_FALLING);
    gpiod_line_settings_set_debounce_period_us(ls, 20000);

    struct gpiod_line_config *lc = gpiod_line_config_new();
    unsigned int off = BTN_OFFSET;
    gpiod_line_config_add_line_settings(lc, &amp;off, 1, ls);

    struct gpiod_request_config *rc = gpiod_request_config_new();
    gpiod_request_config_set_consumer(rc, "breath-ctrl");

    struct gpiod_line_request *req = gpiod_chip_request_lines(chip, rc, lc);
    if (!req) { perror("request_lines"); return 1; }

    struct gpiod_edge_event_buffer *evbuf = gpiod_edge_event_buffer_new(4);

    /* ---- PWM 初始化 ---- */
    if (pwm_init() &lt; 0) { perror("pwm_init"); return 1; }

    enum mode mode = MODE_OFF;
    float phase = 0.0f;                     /* 呼吸相位 0~2π */
    const float step = 0.15f;               /* 每 20ms 推进的相位 */
    struct pollfd pfd = {
        .fd = gpiod_line_request_get_fd(req),
        .events = POLLIN,
    };

    printf("启动：按键切模式（常灭→呼吸→常亮），旋钮调亮度上限\n");

    for (;;) {
        /* 按键事件：20ms 超时，无事件则继续推进呼吸 */
        if (poll(&amp;pfd, 1, 20) &gt; 0 &amp;&amp; (pfd.revents &amp; POLLIN)) {
            int n = gpiod_line_request_read_edge_events(req, evbuf, 4);
            for (int i = 0; i &lt; n; i++)
                mode = (mode + 1) % MODE_MAX;
            printf("模式 → %s\n",
                   mode == MODE_OFF ? "常灭" :
                   mode == MODE_BREATH ? "呼吸" : "常亮");
        }

        float knob = adc_read_ratio();      /* 电位器：亮度上限 */

        switch (mode) {
        case MODE_OFF:
            pwm_set_ratio(0.0f);
            break;
        case MODE_ON:
            pwm_set_ratio(knob);
            break;
        case MODE_BREATH:
            /* sin² 波形近似人眼对数感知，再乘以旋钮上限 */
            phase += step;
            if (phase &gt; 6.2832f) phase -= 6.2832f;
            float s = sinf(phase);
            pwm_set_ratio(s * s * knob);
            break;
        default:
            break;
        }
    }

    /* 到达不了；正常退出应 release request、关 PWM */
    return 0;
}
</code></pre>

设备树节点写法 <p>以 RK3568 为例，SoC 的 <code>rk356x.dtsi</code> 已定义控制器节点：</p> <pre><code>/* rk356x.dtsi 中已有 */
i2c1: i2c@fe5a0000 {
    compatible = "rockchip,rk3568-i2c", "rockchip,rk3399-i2c";
    reg = &lt;0x0 0xfe5a0000 0x0 0x1000&gt;;
    interrupts = &lt;GIC_SPI 47 IRQ_TYPE_LEVEL_HIGH&gt;;
    clocks = &lt;&amp;cru CLK_I2C1&gt;, &lt;&amp;cru PCLK_I2C1&gt;;
    ...
    status = "disabled";        /* 默认关闭，板级 dts 打开 */
};
</code></pre> <p>板级 dts 中的典型配置：</p> <pre><code>&amp;i2c1 {
    status = "okay";
    clock-frequency = &lt;400000&gt;;         /* 默认 100k，可提 Fast-mode */

    eeprom@50 {
        compatible = "atmel,24c02";
        reg = &lt;0x50&gt;;                   /* 7 位从机地址 */
        pagesize = &lt;16&gt;;
    };

    tmp102@48 {
        compatible = "ti,tmp102";
        reg = &lt;0x48&gt;;
    };
};
</code></pre> <p>要点：<code>reg</code> 是 7 位地址（与 B-B.3.2 的约定一致）；子节点的单元地址（<code>@50</code>）必须与 <code>reg</code> 一致；<code>clock-frequency</code> 按总线上最慢设备定（回看 B-B.3.1）。</p>

设备树节点写法 <p>RK3568 的 <code>rk356x.dtsi</code> 已定义控制器（<code>spi1: spi@fe620000</code>，默认 disabled），板级 dts 使能并挂设备：</p> <pre><code>&amp;spi1 {
    status = "okay";
    pinctrl-names = "default";
    pinctrl-0 = &lt;&amp;spi1m0_cs0 &amp;spi1m0_pins&gt;;

    flash@0 {
        compatible = "jedec,spi-nor";
        reg = &lt;0&gt;;                          /* 片选号，不是地址 */
        spi-max-frequency = &lt;50000000&gt;;     /* 按从设备上限与走线定 */
    };
};
</code></pre> <p>与 I2C 设备树的差异点：</p>    属性 含义 注意     <code>reg</code> 片选号（0/1/2…），不是从机地址 SPI 靠 CS 选人，无地址概念   <code>spi-max-frequency</code> 该设备 SCLK 上限 必填，按手册与走线取小   <code>spi-cpol</code> / <code>spi-cpha</code> 时钟极性/相位 布尔属性，存在即置 1，不要写 <code>= &lt;1&gt;</code>   <code>spi-lsb-first</code> 位序 默认 MSB-first     <p>⚠️ <code>spi-cpol = &lt;1&gt;</code> 编译不报错但语义不规范——布尔属性靠"存在/不存在"表达。需要 Mode 3 就写 <code>spi-cpol; spi-cpha;</code> 两行，需要 Mode 0 就什么都不写。</p>

第四步：底层验证（spidev 读 JEDEC ID） <p>框架之下，spi-nor 做的就是把 B-B.4.2 的帧发到总线上。用 spidev 绕过框架直接发命令，验证理解（需设备树挂 spidev 节点，或临时解绑 spi-nor 后用 <code>SPI_IOC</code>）：</p> <pre><code>/* w25q_id.c — spidev 读 W25Q128 JEDEC ID 与状态寄存器 */
#include &lt;stdio.h&gt;
#include &lt;fcntl.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/ioctl.h&gt;
#include &lt;linux/spi/spidev.h&gt;

static int xfer(int fd, unsigned char *tx, unsigned char *rx, int len)
{
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
    };
    return ioctl(fd, SPI_IOC_MESSAGE(1), &amp;tr);
}

int main(void)
{
    int fd = open("/dev/spidev1.0", O_RDWR);
    if (fd &lt; 0) { perror("open"); return 1; }

    unsigned char mode = SPI_MODE_0, bits = 8;
    unsigned int speed = 10000000;
    ioctl(fd, SPI_IOC_WR_MODE, &amp;mode);
    ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &amp;bits);
    ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &amp;speed);

    /* 0x9F JEDEC ID：1 字节命令 + 3 字节读（全双工同帧） */
    unsigned char tx[4] = { 0x9F, 0, 0, 0 }, rx[4] = { 0 };
    xfer(fd, tx, rx, 4);
    printf("JEDEC ID: %02X %02X %02X  %s\n", rx[1], rx[2], rx[3],
           (rx[1] == 0xEF &amp;&amp; rx[3] == 0x18) ? "(W25Q128JV OK)" : "(型号不符!)");

    /* 0x05 状态寄存器：bit0 WIP 应为 0（空闲） */
    unsigned char tx2[2] = { 0x05, 0 }, rx2[2] = { 0 };
    xfer(fd, tx2, rx2, 2);
    printf("Status Reg1: 0x%02X (WIP=%d)\n", rx2[1], rx2[1] &amp; 1);

    close(fd);
    return 0;
}
</code></pre> <pre><code>aarch64-linux-gnu-gcc -o w25q_id w25q_id.c
./w25q_id
# JEDEC ID: EF 40 18  (W25Q128JV OK)
# Status Reg1: 0x00 (WIP=0)
</code></pre> <p>帧级对照：<code>tx</code> 数组前 1 字节是命令、后 3 字节是占位时钟——SPI 全双工，"读 3 字节"就是"边发 3 个无关字节边收 3 字节"，这正是 B-B.4.2 三段式帧在代码里的样子。</p>

设备树 serial 节点 <p>ARM SoC 的 UART 走 platform 总线，资源由设备树描述。RK3568 的 UART2（<code>rk356x.dtsi</code>）：</p> <pre><code>uart2: serial@fe660000 {
    compatible = "rockchip,rk3568-uart", "snps,dw-apb-uart";
    reg = &lt;0x0 0xfe660000 0x0 0x100&gt;;
    interrupts = &lt;GIC_SPI 118 IRQ_TYPE_LEVEL_HIGH&gt;;
    clocks = &lt;&amp;cru SCLK_UART2&gt;, &lt;&amp;cru PCLK_UART2&gt;;
    clock-names = "baudclk", "apb_pclk";
    dmas = &lt;&amp;dmac0 4&gt;, &lt;&amp;dmac0 5&gt;;
    pinctrl-0 = &lt;&amp;uart2m0_xfer&gt;;
    pinctrl-names = "default";
    reg-io-width = &lt;4&gt;;
    reg-shift = &lt;2&gt;;
    status = "disabled";
};
</code></pre> <p>SoC 级 dtsi 已预置寄存器、时钟、DMA 与默认引脚组（M0），板级 dts 通常只需打开：</p> <pre><code>/ {
    aliases {
        serial2 = &amp;uart2;              // 决定 /dev/ttyS2 的编号
    };
};

&amp;uart2 {
    status = "okay";
};
</code></pre> <p>要换用 M1 引脚组时覆写 <code>pinctrl-0 = &lt;&amp;uart2m1_xfer&gt;;</code> 即可。<code>aliases</code> 里的 <code>serialN</code> 编号直接映射到 <code>/dev/ttySN</code>——改别名比改驱动代码更常用于"让 ttyS2 变成 ttyS1"。</p>  <p>⚠️ 复制了节点忘了 <code>status = "okay"</code>：dtsi 默认 disabled，内核 probe 直接跳过，<code>/dev/ttyS2</code> 根本不会出现。设备节点缺失时先查 status，再查 dmesg 里有没有 probe 报错。</p>

实例骨架：libmodbus 读温湿度变送器 <p>工业场景典型连接：PLC 或嵌入式网关作主站，RS-485 挂温湿度变送器（地址拨码 = 1，9600 8N1，寄存器 0x0001 = 温度 ×0.1 °C，0x0002 = 湿度 ×0.1 %RH）。接线三原则：A→A、B→B、GND 必须共地；总线两端各 120 Ω。</p> <p>libmodbus 最小应用骨架：</p> <pre><code>#include &lt;modbus/modbus.h&gt;

modbus_t *ctx = modbus_new_rtu("/dev/ttyS3", 9600, 'N', 8, 1);
modbus_set_slave(ctx, 1);                       // 从机地址
modbus_set_response_timeout(ctx, 1, 0);         // 1 秒响应超时
modbus_connect(ctx);

uint16_t reg[2];
int rc = modbus_read_registers(ctx, 0x0001, 2, reg);   // 功能码 0x03
if (rc == 2) {
    printf("温度 %.1f°C  湿度 %.1f%%RH\n", reg[0] / 10.0, reg[1] / 10.0);
}

modbus_close(ctx);
modbus_free(ctx);
</code></pre> <p>多从机轮询就是循环里 <code>modbus_set_slave()</code> 换地址再读，设备间留约 50 ms 间隔避免总线争抢。完整工程代码（错误重试、断线重连、CRC 验证演示）在扩展篇实战项目展开，这里掌握调用顺序即可。</p> <p>抓包定位用 socat 做中间人，不抢占主程序的串口：</p> <pre><code>socat -x /dev/ttyS3,raw,echo=0,b9600 PTY,link=/dev/virtual_tty0
# 主程序改连 /dev/virtual_tty0，socat 的 -x 输出全量十六进制流量
</code></pre>

第二步：硬件接线与设备树 <p>UART 交叉接线：模块 TX 接 SoC RX。NEO-6M 是单向输出场景，SoC 的 TX 可以不接，但接上可用于下发 UBX 配置命令（进阶）。</p> <p>  RK3568 UART4（serial@fe680000）  NEO-6M 模块   UART4_TX → RX   TX → UART4_RX  GND GND  3.3V VCC TX/RX 交叉、必须共地；模块 TTL 电平 3.3 V 直连安全 </p>  <p>⚠️ 部分 GPS 模块标称 5 V 供电时 TX/RX 也是 5 V 电平——直连会损伤 SoC 的 3.3 V IO。确认模块丝印或手册的 IO 电平；5 V 电平的模块中间加电平转换（TXS0102）或分压电阻。</p>  <p>设备树使能 UART4（SoC 级 dtsi 已预置寄存器/时钟/DMA/默认引脚组）：</p> <pre><code>/ {
    aliases {
        serial2 = &amp;uart2;      // 调试 console（已有）
        serial4 = &amp;uart4;      // GPS
    };
};

&amp;uart4 {
    status = "okay";
};
</code></pre> <p>重启后确认：</p> <pre><code>dmesg | grep fe680000
# fe680000.serial: ttyS4 at MMIO 0xfe680000 (irq = 32, base_baud = 1500000) is a 16550A
ls -l /dev/ttyS4
</code></pre> <p><code>base_baud = 1500000</code> 是 UART 的基准时钟能力，与 GPS 的 9600 工作波特率无关——后者由用户态 termios 设置。</p>

第五步：termios 配置与 NMEA 解析程序 <p>完整程序：配置串口 9600 8N1 raw → 逐字节组帧 → 校验和验证 → 解析 <code>$GPGGA</code> 提取经纬度。</p> <pre><code>/* gps_nmea_parser.c
 * 交叉编译：${CC} -o gps_parser gps_nmea_parser.c
 * 运行：./gps_parser /dev/ttyS4
 */
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;fcntl.h&gt;
#include &lt;unistd.h&gt;
#include &lt;termios.h&gt;
#include &lt;errno.h&gt;

#define BUFFER_SIZE  256
#define NMEA_MAX_LEN 82

/* 配置串口：9600 8N1，原始模式 */
static int setup_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd &lt; 0) { perror("open"); return -1; }

    struct termios tty;
    memset(&amp;tty, 0, sizeof(tty));
    if (tcgetattr(fd, &amp;tty) != 0) { perror("tcgetattr"); close(fd); return -1; }

    cfsetispeed(&amp;tty, B9600);
    cfsetospeed(&amp;tty, B9600);

    tty.c_cflag &amp;= ~PARENB;              /* 无校验 */
    tty.c_cflag &amp;= ~CSTOPB;              /* 1 位停止位 */
    tty.c_cflag &amp;= ~CSIZE;
    tty.c_cflag |= CS8;                  /* 8 数据位 */
    tty.c_cflag |= CREAD | CLOCAL;       /* 使能接收，忽略 Modem 控制线 */

    /* 原始模式：绕过 ldisc 的一切输入/输出处理 */
    tty.c_lflag &amp;= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &amp;= ~(IXON | IXOFF | IXANY | ICRNL | INLCR | IGNCR);
    tty.c_oflag &amp;= ~OPOST;

    tty.c_cc[VMIN]  = 0;                 /* 非阻塞读 */
    tty.c_cc[VTIME] = 5;                 /* 500 ms 超时 */

    if (tcsetattr(fd, TCSANOW, &amp;tty) != 0) { perror("tcsetattr"); close(fd); return -1; }

    tcflush(fd, TCIOFLUSH);              /* 丢弃配置前进入的残留字节 */
    return fd;
}

/* NMEA 校验：$ 与 * 之间所有字符 XOR */
static int nmea_checksum(const char *sentence)
{
    unsigned char checksum = 0;
    while (*sentence &amp;&amp; *sentence != '*') {
        checksum ^= *sentence++;
    }
    return checksum;
}

/* 解析 $GPGGA，输出经纬度（十进制度）、定位质量、卫星数 */
static int parse_gpgga(const char *sentence, double *latitude, double *longitude,
                       int *fix_quality, int *num_satellites)
{
    char buf[NMEA_MAX_LEN];
    strncpy(buf, sentence, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    /* 先验校验和，数据在链路上出错时直接丢弃 */
    char *star = strchr(buf, '*');
    if (!star) return -1;

    int checksum;
    sscanf(star + 1, "%2x", &amp;checksum);
    *star = '\0';
    if (nmea_checksum(buf + 1) != checksum) return -1;

    /* 按逗号切字段 */
    char *token = strtok(buf, ",");
    if (!token || strcmp(token, "$GPGGA") != 0) return -1;

    strtok(NULL, ",");                          /* UTC 时间，本例不用 */
    char *lat_str  = strtok(NULL, ",");         /* ddmm.mmmm */
    char *ns       = strtok(NULL, ",");         /* N/S */
    char *lon_str  = strtok(NULL, ",");         /* dddmm.mmmm */
    char *ew       = strtok(NULL, ",");         /* E/W */
    char *fix_str  = strtok(NULL, ",");         /* 定位质量 */
    char *sats_str = strtok(NULL, ",");         /* 卫星数 */

    if (!lat_str || !lon_str || !ns || !ew || !fix_str) return -1;

    *fix_quality    = atoi(fix_str);
    *num_satellites = sats_str ? atoi(sats_str) : 0;

    /* ddmm.mmmm → 十进制度：度 + 分/60 */
    double lat_deg, lat_min, lon_deg, lon_min;
    sscanf(lat_str, "%2lf%lf", &amp;lat_deg, &amp;lat_min);
    sscanf(lon_str, "%3lf%lf", &amp;lon_deg, &amp;lon_min);

    *latitude  = lat_deg + lat_min / 60.0;
    *longitude = lon_deg + lon_min / 60.0;

    if (ns[0] == 'S') *latitude  = -*latitude;
    if (ew[0] == 'W') *longitude = -*longitude;
    return 0;
}

int main(int argc, char *argv[])
{
    const char *device = (argc &gt; 1) ? argv[1] : "/dev/ttyS4";

    printf("Opening GPS device: %s\n", device);
    int fd = setup_uart(device);
    if (fd &lt; 0) return 1;

    printf("Waiting for GPS fix (cold start may take 30-60s)...\n\n");

    char buffer[BUFFER_SIZE];
    char line[NMEA_MAX_LEN];
    int line_pos = 0;

    while (1) {
        int n = read(fd, buffer, sizeof(buffer) - 1);
        if (n &lt; 0) {
            if (errno == EAGAIN) continue;
            perror("read");
            break;
        }

        /* 逐字节组帧：$ 开始，\n 结束；read 不保证按行返回 */
        for (int i = 0; i &lt; n; i++) {
            if (buffer[i] == '$') line_pos = 0;         /* 新语句起点 */
            if (line_pos &lt; (int)sizeof(line) - 1) line[line_pos++] = buffer[i];

            if (buffer[i] == '\n' &amp;&amp; line_pos &gt; 0) {
                line[line_pos] = '\0';

                if (strncmp(line, "$GPGGA", 6) == 0) {
                    double lat, lon;
                    int fix, sats;
                    if (parse_gpgga(line, &amp;lat, &amp;lon, &amp;fix, &amp;sats) == 0) {
                        printf("[Fix=%d, Sats=%2d] Lat=%.6f, Lon=%.6f\n",
                               fix, sats, lat, lon);
                        if (fix == 0) printf("  -&gt; no fix yet, keep waiting\n");
                    }
                }
                line_pos = 0;
            }
        }
    }

    close(fd);
    return 0;
}
</code></pre> <p>三个实现要点：</p> <ol> <li>组帧必须自己做：<code>read()</code> 返回的字节数与 NMEA 行边界无关（可能半行、可能多行），所以逐字节找 <code>$</code> 起点和 <code>\n</code> 终点。用 <code>fgets</code> 按行读串口是新手常见错误。</li> <li>raw 模式不可省：少了 <code>c_iflag</code> 那一行，数据里的 0x0D 被转成 0x0A、0x11/0x13 被当流控字符吞掉，校验和验证就会间歇性失败。</li> <li>校验和先行：先验 XOR 再解析字段，链路毛刺产生的坏帧在第一步就被丢弃，不会污染位置数据。</li> </ol>

设备树：主线绑定格式 <p>以下格式经 v6.6 <code>Documentation/devicetree/bindings/i3c/i3c.yaml</code> 核实，与网上大量二手文章的写法不同，请以此为准：</p> <pre><code>&amp;i3c0 {
    pinctrl-names = "default";
    pinctrl-0 = &lt;&amp;pinctrl_i3c0&gt;;
    #address-cells = &lt;3&gt;;
    #size-cells = &lt;0&gt;;
    i3c-scl-hz = &lt;12500000&gt;;         /* I3C 速率，缺省 12.5 MHz */
    i2c-scl-hz = &lt;400000&gt;;           /* legacy I2C 速率 */
    status = "okay";

    /* I2C legacy 设备：节点名 &lt;type&gt;@&lt;i2c地址&gt;，reg 三元组 */
    bmp280: pressure@76 {
        compatible = "bosch,bmp280";
        reg = &lt;0x76 0x0 0x10&gt;;       /* I2C地址, 0, LVR/速率特性 */
        vdd-supply = &lt;&amp;reg_3v3&gt;;
    };

    /* I3C 设备：节点名 &lt;type&gt;@&lt;静态I2C地址&gt;,&lt;PID&gt; */
    imu: sensor@68,39200144004 {
        compatible = "bosch,bmi08x-accel";
        reg = &lt;0x68 0x392 0x144004&gt;; /* 静态地址, PID高16位(厂商ID&lt;&lt;1), PID低32位 */
        assigned-address = &lt;0xa&gt;;    /* 期望的动态地址 */
    };
};
</code></pre> <p>三个要点：</p> <ol> <li>I3C 设备节点通常可以不写：DAA 使设备可被发现，只有需要附加资源（时钟、供电、assigned-address 预占地址）时才需要描述。这与 I2C"必须写节点"是本质区别。</li> <li><code>assigned-address</code> 的分配路径：有静态地址走 SETDASA，无静态地址走 ENTDAA + SETNEWDA——对应 B-B.6.2 的 CCC 机制。</li> <li><code>i2c@</code> 形式的旧写法（原文档历史版本）已废弃；I2C 子节点在 I3C 总线下用普通 <code>&lt;type&gt;@&lt;addr&gt;</code> 命名，reg 扩为三元组。I3C 控制器会为 legacy 设备创建一条 I2C adapter，BMP280 这类设备仍由标准 I2C 驱动接管，驱动零改动。</li> </ol>

驱动骨架（probe + 私有传输 + IBI） <p>把前述 API 串成可编译的最小骨架：</p> <pre><code>#include &lt;linux/i3c/device.h&gt;
#include &lt;linux/i3c/master.h&gt;
#include &lt;linux/workqueue.h&gt;

struct sensor_data {
    struct i3c_device *i3cdev;
    struct work_struct ibi_work;
    s16 accel[3];
};

static void sensor_ibi_work(struct work_struct *work)
{
    struct sensor_data *data = container_of(work, struct sensor_data, ibi_work);
    /* workqueue 上下文：可安全做私有传输读数据 */
    struct i3c_priv_xfer xfers[2];
    u8 reg = BMI088_ACC_X_LSB;
    u8 rx[6];

    xfers[0] = (struct i3c_priv_xfer){ .rnw = false, .len = 1, .data.out = &amp;reg };
    xfers[1] = (struct i3c_priv_xfer){ .rnw = true,  .len = 6, .data.in = rx };
    if (i3c_device_do_priv_xfers(data-&gt;i3cdev, xfers, 2))
        return;

    data-&gt;accel[0] = (s16)(rx[1] &lt;&lt; 8 | rx[0]);
    data-&gt;accel[1] = (s16)(rx[3] &lt;&lt; 8 | rx[2]);
    data-&gt;accel[2] = (s16)(rx[5] &lt;&lt; 8 | rx[4]);
}

static void sensor_ibi_handler(struct i3c_device *i3cdev,
                               const struct i3c_ibi_payload *payload)
{
    struct sensor_data *data = i3cdev_get_drvdata(i3cdev);
    schedule_work(&amp;data-&gt;ibi_work);        /* 中断上下文只调度，不读写 */
}

static int sensor_i3c_probe(struct i3c_device *i3cdev)
{
    struct i3c_ibi_setup setup = {
        .handler = sensor_ibi_handler,
        .max_payload_len = 0,
        .num_slots = 1,
    };
    struct sensor_data *data;
    int ret;

    data = devm_kzalloc(&amp;i3cdev-&gt;dev, sizeof(*data), GFP_KERNEL);
    if (!data)
        return -ENOMEM;
    data-&gt;i3cdev = i3cdev;
    i3cdev_set_drvdata(i3cdev, data);
    INIT_WORK(&amp;data-&gt;ibi_work, sensor_ibi_work);

    /* 1. 读 Chip ID 验证通信（两阶段 priv_xfer，代码同前文） */
    /* 2. 初始化传感器寄存器：量程、ODR、DRDY 使能            */

    /* 3. 申请并启用 IBI */
    ret = i3c_device_request_ibi(i3cdev, &amp;setup);
    if (!ret)
        i3c_device_enable_ibi(i3cdev);
    return 0;
}

static void sensor_i3c_remove(struct i3c_device *i3cdev)
{
    i3c_device_disable_ibi(i3cdev);
    i3c_device_free_ibi(i3cdev);
}

static const struct i3c_device_id sensor_i3c_ids[] = {
    I3C_DEVICE(0x392, 0x1440),      /* 厂商 ID, part ID —— 按器件手册填 */
    { }
};
MODULE_DEVICE_TABLE(i3c, sensor_i3c_ids);

static struct i3c_driver sensor_i3c_driver = {
    .driver = { .name = "sensor-i3c" },
    .probe = sensor_i3c_probe,
    .remove = sensor_i3c_remove,
    .id_table = sensor_i3c_ids,
};
module_i3c_driver(sensor_i3c_driver);
MODULE_LICENSE("GPL");
</code></pre>

驱动注册与匹配 <p>PCI 驱动与 platform 驱动（第 11 章）同构：一个描述"我是谁"的结构体、一张描述"我支持谁"的 ID 表、一对 probe/remove 回调。不同的是匹配依据——platform 驱动靠设备树 compatible 字符串，PCI 驱动靠枚举读到的 Vendor ID / Device ID：</p> <pre><code>/* ID 表：本驱动支持哪些设备 */
static const struct pci_device_id my_pcie_ids[] = {
    { PCI_DEVICE(0x8086, 0x2725) },   /* Intel AX210 */
    { PCI_DEVICE(0x144d, 0xa808) },   /* Samsung NVMe */
    { 0, }                            /* 结束标记 */
};
MODULE_DEVICE_TABLE(pci, my_pcie_ids);

static struct pci_driver my_pcie_driver = {
    .name     = "my_pcie_drv",
    .id_table = my_pcie_ids,
    .probe    = my_pcie_probe,
    .remove   = my_pcie_remove,
};

module_pci_driver(my_pcie_driver);   /* 注册/注销一体宏 */
</code></pre> <p><code>MODULE_DEVICE_TABLE</code> 宏把 ID 表导出给用户空间——设备插入时 udev 据此自动加载对应内核模块，这就是 PCIe 设备"插上来驱动自己就来了"的完整链路：枚举读到 ID → 生成 modalias → udev 匹配 → modprobe 加载 → probe 被调用。</p>  <p>💡 除了精确 ID 匹配，还有通配匹配：<code>PCI_DEVICE_CLASS(0x010802, ~0)</code> 匹配所有 NVMe 类设备（靠 10.2 讲的 Class Code）——nvme 驱动就是这样成批通吃所有厂商 NVMe 盘的。你的自定义驱动一般走精确 ID；当设备可换料（同一功能不同厂商）时才考虑 class 匹配。</p>  <p>probe 永远不被调用的头号原因就是 ID 对不上：拿 <code>lspci -nn</code> 的实际输出（方括号里的 <code>[8086:2725]</code>）逐一核对 ID 表，注意 Subsystem ID 不参与默认匹配。</p>

probe 完整流程：每一步对应一个硬件动作 <p><code>probe()</code> 里的 API 调用顺序不是惯例，是依赖关系——每步失败的症状都不同，记住这张表，驱动加载失败时按症状反查步骤：</p>    步骤 API 对应 10.2 的哪个概念 失败时的典型症状     1. 启用设备 <code>pci_enable_device()</code> Command 寄存器置位、资源激活 后续一切访问无效；dmesg 报 "can't enable device"   2. 独占 BAR 区域 <code>pci_request_regions()</code> resource 树占用标记 报 "BAR in use"——上一个驱动没释放干净   3. 设为总线主 <code>pci_set_master()</code> Command.Bit2 Bus Master 不调用则 DMA 静默失败——寄存器读写正常但数据不动   4. 映射 BAR <code>pci_iomap(pdev, 0, 0)</code> BAR0 的 CPU 侧地址 返回 NULL：BAR 未使能或地址冲突   5. 设 DMA 掩码 <code>dma_set_mask_and_coherent()</code> 设备可寻址内存范围 高内存机器上 DMA 数据损坏（地址截断）   6. 申请中断 <code>pci_alloc_irq_vectors()</code> MSI/MSI-X Capability 中断永远不触发   7. 初始化硬件 写设备寄存器 —— 视设备而定    <p>完整骨架（v6.6 现代 API）：</p> <pre><code>struct my_priv {
    struct pci_dev *pdev;
    void __iomem *bar0;
    int nvec;
};

static int my_pcie_probe(struct pci_dev *pdev, const struct pci_device_id *id)
{
    struct my_priv *priv;
    int err;

    priv = devm_kzalloc(&amp;pdev-&gt;dev, sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;
    priv-&gt;pdev = pdev;
    pci_set_drvdata(pdev, priv);

    /* 1+2 合并：使能设备并请求全部 BAR 区域（devm 托管，免手动释放） */
    err = pcim_enable_device(pdev);
    if (err)
        return err;
    err = pcim_iomap_regions(pdev, BIT(0), "my_pcie_drv");
    if (err)
        return err;

    /* 3. 允许设备做 Bus Master——DMA 的前提 */
    pci_set_master(pdev);

    /* 4. 取 BAR0 映射基地址，之后 readl/writel 访问寄存器 */
    priv-&gt;bar0 = pcim_iomap_table(pdev)[0];
    if (!priv-&gt;bar0)
        return -ENOMEM;

    /* 5. DMA 掩码：先试 64 位，失败回退 32 位 */
    err = dma_set_mask_and_coherent(&amp;pdev-&gt;dev, DMA_BIT_MASK(64));
    if (err)
        err = dma_set_mask_and_coherent(&amp;pdev-&gt;dev, DMA_BIT_MASK(32));
    if (err) {
        dev_err(&amp;pdev-&gt;dev, "no usable DMA configuration\n");
        return err;
    }

    /* 6. 中断：优先 MSI-X 多向量，依次自动降级 MSI → INTx */
    priv-&gt;nvec = pci_alloc_irq_vectors(pdev, 1, 4,
                                       PCI_IRQ_MSIX | PCI_IRQ_MSI | PCI_IRQ_LEGACY);
    if (priv-&gt;nvec &lt; 0)
        return priv-&gt;nvec;
    err = devm_request_irq(&amp;pdev-&gt;dev, pci_irq_vector(pdev, 0),
                           my_irq_handler, 0, "my_pcie_drv", priv);
    if (err)
        return err;

    /* 7. 设备硬件初始化：写寄存器、建描述符环…… */
    my_hw_init(priv);

    dev_info(&amp;pdev-&gt;dev, "probed: bar0=%p, vectors=%d\n", priv-&gt;bar0, priv-&gt;nvec);
    return 0;
}
</code></pre> <p>两处相对老代码的现代化修正，值得展开：</p> <p><code>pcim_*</code> 与 <code>devm_*</code> 托管 API（11.3.4 的 devm 机制在 PCI 侧的延伸）：<code>pcim_enable_device()</code>、<code>pcim_iomap_regions()</code> 申请的资源随设备自动释放，probe 出错返回时不用手写七八个 <code>goto</code> 回退标签——老代码里"按相反顺序释放资源"的错误处理阶梯，被资源托管整个消掉了。新代码一律用托管版。</p> <p><code>pci_alloc_irq_vectors()</code> 取代 <code>pci_enable_msi()</code>：这是 v6.6 的统一中断分配 API——传入想要的最小/最大向量数和支持的中断类型（<code>PCI_IRQ_MSIX | PCI_IRQ_MSI | PCI_IRQ_LEGACY</code>），内核按优先级自动尝试并降级。取第 i 个向量的中断号用 <code>pci_irq_vector(pdev, i)</code>——不要再用 <code>pdev-&gt;irq + i</code> 推算，MSI-X 的向量号并不保证连续，那是旧 MSI 时代的侥幸写法。</p>

驱动实现：从 probe 到 BAR 寄存器访问 <p>probe 骨架沿用 10.3 的七步（托管 API 版），这里补上 EP 卡特有的部分——探活读 ID 与寄存器访问封装：</p> <pre><code>#include &lt;linux/pci.h&gt;
#include &lt;linux/dma-mapping.h&gt;

#define REG_ID          0x00
#define REG_CTRL        0x08
#define REG_STATUS      0x0c
#define REG_IRQ_STATUS  0x10
#define REG_IRQ_ENABLE  0x14
#define REG_DESC_LO     0x20
#define REG_DESC_HI     0x24
#define REG_DESC_NUM    0x28

#define CARD_MAGIC      0xcaed0001
#define CTRL_ENABLE     BIT(0)
#define CTRL_DMA_START  BIT(1)
#define ST_DMA_DONE     BIT(1)

struct ep_card {
    struct pci_dev *pdev;
    void __iomem *bar0;
    struct ep_desc *ring;      /* 一致性 DMA：描述符环 */
    dma_addr_t ring_dma;
    int nvec;
};

struct ep_desc {               /* 与 FPGA 约定的描述符格式 */
    __le32 addr_lo;
    __le32 addr_hi;
    __le32 len;
    __le32 flags;
};

static int ep_probe(struct pci_dev *pdev, const struct pci_device_id *id)
{
    struct ep_card *card;
    u32 magic;
    int err;

    card = devm_kzalloc(&amp;pdev-&gt;dev, sizeof(*card), GFP_KERNEL);
    if (!card)
        return -ENOMEM;
    card-&gt;pdev = pdev;
    pci_set_drvdata(pdev, card);

    err = pcim_enable_device(pdev);
    if (err)
        return err;
    err = pcim_iomap_regions(pdev, BIT(0), "ep_card");
    if (err)
        return err;
    pci_set_master(pdev);
    card-&gt;bar0 = pcim_iomap_table(pdev)[0];
    if (!card-&gt;bar0)
        return -ENOMEM;

    /* 探活：读 ID 寄存器验证 BAR 映射正确——不对就是映射/翻译出了问题 */
    magic = readl(card-&gt;bar0 + REG_ID);
    if (magic != CARD_MAGIC) {
        dev_err(&amp;pdev-&gt;dev, "bad magic 0x%08x (expect 0x%08x)\n", magic, CARD_MAGIC);
        return -ENODEV;
    }

    err = dma_set_mask_and_coherent(&amp;pdev-&gt;dev, DMA_BIT_MASK(64));
    if (err)
        dma_set_mask_and_coherent(&amp;pdev-&gt;dev, DMA_BIT_MASK(32));

    /* 一致性 DMA 分配描述符环：64 个描述符 */
    card-&gt;ring = dma_alloc_coherent(&amp;pdev-&gt;dev,
                                    64 * sizeof(struct ep_desc),
                                    &amp;card-&gt;ring_dma, GFP_KERNEL);
    if (!card-&gt;ring)
        return -ENOMEM;

    /* MSI-X：先申请 2 向量（向量0=DMA完成，向量1=错误上报） */
    card-&gt;nvec = pci_alloc_irq_vectors(pdev, 2, 2, PCI_IRQ_MSIX);
    if (card-&gt;nvec &lt; 0)
        card-&gt;nvec = pci_alloc_irq_vectors(pdev, 1, 1,
                                           PCI_IRQ_MSI | PCI_IRQ_LEGACY);
    if (card-&gt;nvec &lt; 0)
        return card-&gt;nvec;
    err = devm_request_irq(&amp;pdev-&gt;dev, pci_irq_vector(pdev, 0),
                           ep_irq_handler, 0, "ep_card", card);
    if (err)
        return err;

    /* 使能设备与中断 */
    writel(0x1, card-&gt;bar0 + REG_IRQ_ENABLE);
    writel(CTRL_ENABLE, card-&gt;bar0 + REG_CTRL);

    dev_info(&amp;pdev-&gt;dev, "ep_card probed, magic ok, nvec=%d\n", card-&gt;nvec);
    return 0;
}
</code></pre> <p>注意 probe 里那个 <code>readl(REG_ID)</code> 探活——它是 EP 卡驱动的标准动作，也是排障分水岭：ID 读对，说明枚举、BAR 分配、地址翻译、映射四层全通；ID 读错（常见读回全 0 或全 1），问题一定在这四层里，按联调一节的顺序查。</p>

DMA 传输实现：描述符环转起来 <p>发起一次"主机 → 卡"的 DMA 传输，驱动侧的完整动作：</p> <pre><code>int ep_dma_send(struct ep_card *card, void *buf, size_t len)
{
    struct ep_desc *d = &amp;card-&gt;ring[0];
    dma_addr_t data_dma;

    /* 1. 流式映射数据缓冲区（10.3 的 Cache 同步在 map 里完成） */
    data_dma = dma_map_single(&amp;card-&gt;pdev-&gt;dev, buf, len, DMA_TO_DEVICE);
    if (dma_mapping_error(&amp;card-&gt;pdev-&gt;dev, data_dma))
        return -ENOMEM;

    /* 2. 填描述符 */
    d-&gt;addr_lo = cpu_to_le32(lower_32_bits(data_dma));
    d-&gt;addr_hi = cpu_to_le32(upper_32_bits(data_dma));
    d-&gt;len     = cpu_to_le32(len);
    d-&gt;flags   = cpu_to_le32(DESC_VALID);

    /* 3. 告诉硬件环在哪、几个描述符，然后按门铃 */
    writel(lower_32_bits(card-&gt;ring_dma), card-&gt;bar0 + REG_DESC_LO);
    writel(upper_32_bits(card-&gt;ring_dma), card-&gt;bar0 + REG_DESC_HI);
    writel(1, card-&gt;bar0 + REG_DESC_NUM);
    writel(CTRL_ENABLE | CTRL_DMA_START, card-&gt;bar0 + REG_CTRL);

    /* 4. 等完成中断，然后解除映射 */
    wait_for_completion_timeout(&amp;card-&gt;dma_done, HZ);
    dma_unmap_single(&amp;card-&gt;pdev-&gt;dev, data_dma, len, DMA_TO_DEVICE);
    return 0;
}
</code></pre> <p>中断处理函数——读挂起位、清中断、唤醒等待者：</p> <pre><code>static irqreturn_t ep_irq_handler(int irq, void *data)
{
    struct ep_card *card = data;
    u32 pending = readl(card-&gt;bar0 + REG_IRQ_STATUS);

    if (!pending)
        return IRQ_NONE;              /* 共享中断下必须区分"不是我的" */

    writel(pending, card-&gt;bar0 + REG_IRQ_STATUS);   /* 写 1 清除 */
    if (pending &amp; ST_DMA_DONE)
        complete(&amp;card-&gt;dma_done);
    return IRQ_HANDLED;
}
</code></pre> <p>反向传输（卡 → 主机）同构：方向改 <code>DMA_FROM_DEVICE</code>，完成后 CPU 读数据前由 <code>dma_unmap_single</code> 完成 Cache 失效——10.3 讲的同步语义在这里落地。</p>

路径一：现成驱动零代码 [I] <pre><code>/* EC11 旋钮：rotary-encoder 现成驱动 */
rotary {
    compatible = "rotary-encoder";
    gpios = &lt;&amp;gpio1 10 GPIO_ACTIVE_HIGH&gt;, &lt;&amp;gpio1 11 GPIO_ACTIVE_HIGH&gt;;
    linux,axis = &lt;REL_WHEEL&gt;;              /* 上报为滚轮相对事件 */
    rotary-encoder,relative-axis;
    rotary-encoder,steps-per-period = &lt;4&gt;; /* 一个刻度 4 个电平周期 */
    wakeup-source;
};

/* 轻触按键：gpio-keys 现成驱动 */
keys {
    compatible = "gpio-keys";
    mute {
        label = "mute";
        gpios = &lt;&amp;gpio1 12 GPIO_ACTIVE_LOW&gt;;
        linux,code = &lt;KEY_ENTER&gt;;          /* 上报回车键值 */
        debounce-interval = &lt;5&gt;;           /* 框架内建消抖，5ms */
    };
};
</code></pre> <p>零代码拿到的功能：中断注册、消抖、事件上报、<code>/dev/input/eventX</code> 节点、唤醒源——全部来自现成驱动。源码走读（看它替你做了什么）：<code>drivers/input/misc/rotary_encoder.c</code> 的 probe 解析 <code>gpios</code>/<code>linux,axis</code> 属性、注册 threaded IRQ、handler 里读两相电平判定方向后 <code>input_report_rel()</code>；<code>drivers/input/keyboard/gpio-keys.c</code> 的 <code>debounce-interval</code> 用 <code>mod_timer</code> 顺延合并（D.5 范式一的框架内建版）。</p>

最小骨架：SHT3x 案例 [I→E] <p>SHT3x：I2C 温湿度传感器，一条命令启动测量，读回 4 字节（温度 2B + 湿度 2B）。</p> <pre><code>#include &lt;linux/module.h&gt;
#include &lt;linux/i2c.h&gt;
#include &lt;linux/iio/iio.h&gt;

#define SHT3X_CMD_MEASURE  0x2400   /* 单次测量，高重复性 */

struct sht3x_data {
    struct i2c_client *client;
    struct mutex lock;
};

/* ① channel 定义：每个物理量一条，info_mask 声明能读什么 */
static const struct iio_chan_spec sht3x_channels[] = {
    {
        .type = IIO_TEMP,
        .info_mask_separate = BIT(IIO_CHAN_INFO_RAW) |
                              BIT(IIO_CHAN_INFO_SCALE) |
                              BIT(IIO_CHAN_INFO_OFFSET),
    }, {
        .type = IIO_HUMIDITYRELATIVE,
        .info_mask_separate = BIT(IIO_CHAN_INFO_RAW) |
                              BIT(IIO_CHAN_INFO_SCALE),
    },
};

/* ② read_raw：框架按 channel + mask 回调进来 */
static int sht3x_read_raw(struct iio_dev *indio_dev,
                          struct iio_chan_spec const *chan,
                          int *val, int *val2, long mask)
{
    struct sht3x_data *data = iio_priv(indio_dev);
    u8 buf[4];
    int ret;
    s16 raw;

    switch (mask) {
    case IIO_CHAN_INFO_RAW:
        mutex_lock(&amp;data-&gt;lock);
        ret = i2c_smbus_write_word_data(data-&gt;client, 0, SHT3X_CMD_MEASURE);
        if (ret &lt; 0)
            goto out;
        msleep(15);                     /* 手册：高重复性测量耗时 15ms */
        ret = i2c_master_recv(data-&gt;client, buf, sizeof(buf));
        if (ret &lt; 0)
            goto out;
        raw = (chan-&gt;type == IIO_TEMP) ? (buf[0] &lt;&lt; 8 | buf[1])
                                       : (buf[2] &lt;&lt; 8 | buf[3]);
        *val = raw;
        ret = IIO_VAL_INT;              /* 返回值类型：整数 */
out:
        mutex_unlock(&amp;data-&gt;lock);
        return ret;

    case IIO_CHAN_INFO_SCALE:
        /* 手册换算公式拆成整数+小数两部分返回 */
        if (chan-&gt;type == IIO_TEMP) {
            *val = 175;  *val2 = 65535;     /* T = raw * 175/65535 - 45 */
        } else {
            *val = 100;  *val2 = 65535;     /* RH = raw * 100/65535 */
        }
        return IIO_VAL_FRACTIONAL;

    case IIO_CHAN_INFO_OFFSET:
        *val = -45;                         /* 温度偏移 */
        return IIO_VAL_INT;
    }
    return -EINVAL;
}

static const struct iio_info sht3x_info = {
    .read_raw = sht3x_read_raw,
};

/* ③ 注册 */
static int sht3x_probe(struct i2c_client *client)
{
    struct iio_dev *indio_dev;
    struct sht3x_data *data;

    indio_dev = devm_iio_device_alloc(&amp;client-&gt;dev, sizeof(*data));
    if (!indio_dev)
        return -ENOMEM;

    data = iio_priv(indio_dev);
    data-&gt;client = client;
    mutex_init(&amp;data-&gt;lock);

    indio_dev-&gt;name = "sht3x";
    indio_dev-&gt;channels = sht3x_channels;
    indio_dev-&gt;num_channels = ARRAY_SIZE(sht3x_channels);
    indio_dev-&gt;info = &amp;sht3x_info;
    indio_dev-&gt;modes = INDIO_DIRECT_MODE;      /* 仅直读，无 buffer */

    return devm_iio_device_register(&amp;client-&gt;dev, indio_dev);
}
</code></pre> <p>效果——用户态拿到的是标准化、带单位语义的接口：</p> <pre><code>cat /sys/bus/iio/devices/iio:device0/in_temp_raw
23456
cat /sys/bus/iio/devices/iio:device0/in_temp_scale
175/65535（实际显示为内核换算后的数值形式）
cat /sys/bus/iio/devices/iio:device0/in_temp_offset
-45
</code></pre> <p>三个骨架要点：</p> <ol> <li>read_raw 的返回值不是数据，是"数据怎么解释"：<code>IIO_VAL_INT</code> 表示 *val 就是值；<code>IIO_VAL_FRACTIONAL</code> 表示 值 = val/val2——SCALE/OFFSET 的换算语义由这套返回类型承载，写错类型用户态算出的物理量全错</li> <li>channel 声明与 read_raw 分支必须一一对应：info_mask 声明了 SCALE 而 read_raw 的 switch 没写这个分支，用户态读到 -EINVAL——声明即契约</li> <li><code>devm_iio_device_alloc/register</code>：全 devm 形态，remove 为空（D.1 原则在框架内的延续）</li> </ol>

buffer + trigger：连续采样 [E] <p>直读模式（INDIO_DIRECT_MODE）只解决"问一次答一次"。采集业务的真实需求是按节奏连续采样、批量取走——IIO 的答案是 buffer + trigger：</p> <pre><code>trigger（hrtimer/数据就绪中断）──► 触发采样 ──► 驱动把一帧数据推入 buffer
                                                      │
用户态 ◄── read /dev/iio:device0 ◄── kfifo 式缓冲 ◄──┘
</code></pre> <p>驱动侧增量三步：</p> <pre><code>/* ① 声明扫描元素：连续采样时每帧包含哪些 channel */
static const struct iio_chan_spec sht3x_scan_channels[] = {
    { .type = IIO_TEMP,
      .scan_index = 0,
      .scan_type = { .sign = 's', .realbits = 16, .storagebits = 16,
                     .endianness = IIO_BE, }, },
    /* 湿度 scan_index=1，时间戳通道由框架自动追加 */
};

/* ② trigger handler：触发到来时读一帧推入 buffer */
static irqreturn_t sht3x_trigger_handler(int irq, void *p)
{
    struct iio_poll_func *pf = p;
    struct iio_dev *indio_dev = pf-&gt;indio_dev;
    /* …… 读传感器 → iio_push_to_buffers_with_timestamp() …… */
    return IRQ_HANDLED;
}

/* ③ probe 里挂缓冲 */
    indio_dev-&gt;modes = INDIO_DIRECT_MODE | INDIO_BUFFER_SOFTWARE;
    ret = devm_iio_triggered_buffer_setup(&amp;client-&gt;dev, indio_dev,
                                          NULL, sht3x_trigger_handler, NULL);
</code></pre> <p>trigger 来源三选一：数据就绪中断脚（最省 CPU）、hrtimer 软触发（<code>iio-trig-hrtimer</code>，周期精确）、sysfs 软触发（<code>iio-trig-sysfs</code>，调试手动踢）。概念与 D.4/D.5 的中断/定时器一一对应，只是调度权移交给了 IIO 核心。</p>  <p>💡 trigger handler 运行在中断线程上下文（trigger 是中断时）或软中断路径——里面做 I2C 测量（15ms）会拖垮实时性。正确姿势和 D.4/D.5 相同：handler 只启动转换，数据就绪中断（或第二个 trigger）里再取数推 buffer。</p>

hwmon 驱动的产品级写法 [E] <p>11.1.1 的 mysoctemp.c 展示了最小形态。产品级写法用 <code>hwmon_device_register_with_info</code>——属性文件由框架按 channel 声明自动生成，不写 <code>sysfs_create</code>：</p> <pre><code>#include &lt;linux/hwmon.h&gt;

struct mytemp_data {
    struct i2c_client *client;
    struct mutex lock;
};

/* ① 读回调：按 channel 类型分发，单位是框架规定的毫度/毫伏/毫安 */
static int mytemp_read(struct device *dev, enum hwmon_sensor_types type,
                       u32 attr, int channel, long *val)
{
    struct mytemp_data *data = dev_get_drvdata(dev);
    int raw;

    if (type != hwmon_temp || attr != hwmon_temp_input)
        return -EOPNOTSUPP;

    mutex_lock(&amp;data-&gt;lock);
    raw = i2c_smbus_read_word_data(data-&gt;client, 0x01);  /* 读温度寄存器 */
    mutex_unlock(&amp;data-&gt;lock);
    if (raw &lt; 0)
        return raw;

    *val = (raw &gt;&gt; 4) * 625 / 10;      /* 换算成毫摄氏度：0.0625°C/LSB */
    return 0;
}

static umode_t mytemp_is_visible(const void *drvdata,
                                 enum hwmon_sensor_types type,
                                 u32 attr, int channel)
{
    return 0444;                        /* 只读 */
}

static const struct hwmon_ops mytemp_hwmon_ops = {
    .is_visible = mytemp_is_visible,
    .read = mytemp_read,
};

/* ② channel 声明：框架据此生成 temp1_input 等标准属性 */
static const struct hwmon_channel_info * const mytemp_info[] = {
    HWMON_CHANNEL_INFO(temp, HWMON_T_INPUT),
    NULL
};

static const struct hwmon_chip_info mytemp_chip_info = {
    .ops = &amp;mytemp_hwmon_ops,
    .info = mytemp_info,
};

/* 挂接 thermal 所需的最小 ops：把温度值透传给 thermal 框架（单位同为毫度） */
static int mytemp_get_temp(void *arg, int *temp)
{
    struct mytemp_data *data = arg;
    int raw;

    mutex_lock(&amp;data-&gt;lock);
    raw = i2c_smbus_read_word_data(data-&gt;client, 0x01);
    mutex_unlock(&amp;data-&gt;lock);
    if (raw &lt; 0)
        return raw;
    *temp = (raw &gt;&gt; 4) * 625 / 10;
    return 0;
}

static const struct thermal_zone_of_device_ops mytemp_thermal_ops = {
    .get_temp = mytemp_get_temp,
};

static int mytemp_probe(struct i2c_client *client)
{
    struct mytemp_data *data;
    struct device *hwmon_dev;

    data = devm_kzalloc(&amp;client-&gt;dev, sizeof(*data), GFP_KERNEL);
    if (!data)
        return -ENOMEM;
    data-&gt;client = client;
    mutex_init(&amp;data-&gt;lock);
    i2c_set_clientdata(client, data);

    /* ③ 注册：devm 版，remove 为空 */
    hwmon_dev = devm_hwmon_device_register_with_info(&amp;client-&gt;dev,
                                                     "mytemp", data,
                                                     &amp;mytemp_chip_info, NULL);

    /* ④ 挂接 thermal：一行代码让本传感器成为 thermal zone 的温度源 */
    if (!IS_ERR(hwmon_dev))
        devm_thermal_of_zone_register(hwmon_dev, 0, data, &amp;mytemp_thermal_ops);

    return PTR_ERR_OR_ZERO(hwmon_dev);
}
</code></pre> <p>写法要点三个：</p> <ol> <li>单位是框架契约：hwmon 规定温度输出毫摄氏度、电压毫伏、电流毫安——<code>temp1_input</code> 读出的 <code>23750</code> 表示 23.75°C。换算在驱动里做完，用户态（lm-sensors、telegraf 等）全部按标准单位消费</li> <li>channel 声明生成属性：<code>HWMON_CHANNEL_INFO(temp, HWMON_T_INPUT)</code> 声明后框架自动建 <code>temp1_input</code>，声明 <code>HWMON_T_MAX</code> 就有 <code>temp1_max</code> 及对应写回调——声明即接口</li> <li><code>devm_thermal_of_zone_register</code> 是联动开关：挂上之后，设备树 <code>thermal-zones</code> 里以本传感器为 <code>thermal-sensors</code> 引用的 zone 就能拿到温度。不挂这一行，sensor 只是 sensor，闭环断路</li> </ol>

cooling device 自写：PWM 风扇 [E] <p>thermal 核心调速时，调用的是 cooling device 的 <code>set_cur_state</code>——这个回调的实现就是风扇驱动的核心。三个回调构成全部接口：</p> <pre><code>#include &lt;linux/thermal.h&gt;
#include &lt;linux/pwm.h&gt;

struct fan_data {
    struct pwm_device *pwm;
    struct thermal_cooling_device *cdev;
    unsigned long max_state;            /* 档位总数 - 1，如 4 档 */
};

static int fan_get_max_state(struct thermal_cooling_device *cdev,
                             unsigned long *state)
{
    struct fan_data *data = cdev-&gt;devdata;

    *state = data-&gt;max_state;
    return 0;
}

static int fan_get_cur_state(struct thermal_cooling_device *cdev,
                             unsigned long *state)
{
    struct fan_data *data = cdev-&gt;devdata;
    struct pwm_state p;

    pwm_get_state(data-&gt;pwm, &amp;p);
    *state = p.duty_cycle * data-&gt;max_state / p.period;   /* 占空比→档位 */
    return 0;
}

static int fan_set_cur_state(struct thermal_cooling_device *cdev,
                             unsigned long state)
{
    struct fan_data *data = cdev-&gt;devdata;
    struct pwm_state p;

    if (state &gt; data-&gt;max_state)
        return -EINVAL;

    /* 档位 → PWM 占空比：线性映射，档 0 停转 */
    pwm_get_state(data-&gt;pwm, &amp;p);
    p.duty_cycle = state ? p.period * state / data-&gt;max_state : 0;
    p.enabled = state &gt; 0;
    return pwm_apply_state(data-&gt;pwm, &amp;p);
}

static const struct thermal_cooling_device_ops fan_cooling_ops = {
    .get_max_state = fan_get_max_state,
    .get_cur_state = fan_get_cur_state,
    .set_cur_state = fan_set_cur_state,
};

static int fan_probe(struct platform_device *pdev)
{
    struct fan_data *data;

    data = devm_kzalloc(&amp;pdev-&gt;dev, sizeof(*data), GFP_KERNEL);
    if (!data)
        return -ENOMEM;
    data-&gt;max_state = 4;                                  /* 5 档调速 */
    data-&gt;pwm = devm_pwm_get(&amp;pdev-&gt;dev, NULL);
    if (IS_ERR(data-&gt;pwm))
        return dev_err_probe(&amp;pdev-&gt;dev, PTR_ERR(data-&gt;pwm), "no pwm\n");

    /* 注册为 cooling device：名字 "pwm-fan" 与 DT 的 cooling-device 引用对应 */
    data-&gt;cdev = devm_thermal_cooling_device_register(&amp;pdev-&gt;dev, "pwm-fan",
                                                      data, &amp;fan_cooling_ops);
    return PTR_ERR_OR_ZERO(data-&gt;cdev);
}
</code></pre> <p>内核已有现成 <code>pwm-fan</code> 驱动（<code>drivers/thermal/pwm_fan.c</code>，支持转速计反馈与完整 DT binding）——本篇这个简化版是教学骨架，产品里先用现成驱动，判定逻辑与 D.10 相同：binding 兼容就 DT 声明零代码。</p> <p>设备树接线（结构示意，字段详解见 15.4.2）：</p> <pre><code>thermal-zones {
    soc_thermal {
        thermal-sensors = &lt;&amp;mytemp 0&gt;;      /* 温度源：hwmon 传感器 */
        trips {
            trip0 { temperature = &lt;60000&gt;; type = "active"; };
            trip1 { temperature = &lt;75000&gt;; type = "active"; };
        };
        cooling-maps {
            map0 { trip = &lt;&amp;trip0&gt;; cooling-device = &lt;&amp;fan 1 1&gt;; };
            map1 { trip = &lt;&amp;trip1&gt;; cooling-device = &lt;&amp;fan 2 4&gt;; };
        };
    };
};
</code></pre> <p><code>cooling-maps</code> 里 <code>&lt;&amp;fan 1 1&gt;</code> 的两个数字是该 trip 触发时风扇被允许运行的档位区间——60°C 挂 1 档，75°C 允许 2-4 档，Governor 在区间内选档（策略对比见 15.4.2）。</p>

零代码路径 [I] <pre><code>/* GPIO 状态灯：leds-gpio */
leds {
    compatible = "gpio-leds";
    status {
        label = "green:status";
        gpios = &lt;&amp;gpio1 8 GPIO_ACTIVE_HIGH&gt;;
        linux,default-trigger = "heartbeat";   /* 上电即心跳呼吸 */
        default-state = "on";
    };
    link {
        label = "blue:link";
        gpios = &lt;&amp;gpio1 9 GPIO_ACTIVE_LOW&gt;;
        linux,default-trigger = "netdev";      /* 网口活动灯 */
    };
};

/* PWM 调光灯：pwm-leds */
pwmleds {
    compatible = "pwm-leds";
    backlight_led {
        label = "white:dim";
        pwms = &lt;&amp;pwm2 0 50000&gt;;               /* PWM 通道 + 周期 ns */
        max-brightness = &lt;255&gt;;
    };
};
</code></pre> <p>零代码拿到的服务：<code>/sys/class/leds/green:status/</code> 全套节点、trigger 调度、亮度映射、suspend/resume 处理。验收：</p> <pre><code>cat /sys/class/leds/green:status/trigger
none [heartbeat] timer netdev mtd ...      # 方括号是当前生效的 trigger
echo timer &gt; /sys/class/leds/green:status/trigger
echo 100 &gt; /sys/class/leds/green:status/delay_on   # timer trigger 的占空参数
</code></pre>

自写路径：led_classdev 骨架 [I→E] <p>以一颗 I2C 十六路 LED 驱动芯片（IS31FL 风格）为例，每路注册一个 led_classdev：</p> <pre><code>#include &lt;linux/leds.h&gt;

struct myled_data {
    struct i2c_client *client;
    struct mutex lock;
};

struct myled_channel {
    struct myled_data *chip;
    struct led_classdev cdev;
    int channel;                            /* 0-15 */
};

/* I2C 芯片的写寄存器会睡眠——必须用 blocking 版回调 */
static int myled_brightness_set(struct led_classdev *cdev,
                                enum led_brightness brightness)
{
    struct myled_channel *ch = container_of(cdev, struct myled_channel, cdev);
    int ret;

    mutex_lock(&amp;ch-&gt;chip-&gt;lock);
    ret = i2c_smbus_write_byte_data(ch-&gt;chip-&gt;client,
                                    0x10 + ch-&gt;channel, brightness);
    mutex_unlock(&amp;ch-&gt;chip-&gt;lock);
    return ret;
}

static int myled_probe(struct i2c_client *client)
{
    struct myled_data *data;
    int i, ret;

    data = devm_kzalloc(&amp;client-&gt;dev, sizeof(*data), GFP_KERNEL);
    if (!data)
        return -ENOMEM;
    data-&gt;client = client;
    mutex_init(&amp;data-&gt;lock);

    for (i = 0; i &lt; 16; i++) {
        struct myled_channel *ch;

        ch = devm_kzalloc(&amp;client-&gt;dev, sizeof(*ch), GFP_KERNEL);
        if (!ch)
            return -ENOMEM;
        ch-&gt;chip = data;
        ch-&gt;channel = i;

        ch-&gt;cdev.name = devm_kasprintf(&amp;client-&gt;dev, GFP_KERNEL,
                                       "myled:ch%d", i);
        ch-&gt;cdev.max_brightness = 255;
        ch-&gt;cdev.brightness_set_blocking = myled_brightness_set;
        ch-&gt;cdev.flags = LED_CORE_SUSPENDRESUME;   /* 挂起恢复时框架重放亮度 */

        ret = devm_led_classdev_register(&amp;client-&gt;dev, &amp;ch-&gt;cdev);
        if (ret)
            return dev_err_probe(&amp;client-&gt;dev, ret, "ch%d register failed\n", i);
    }
    return 0;
}
</code></pre> <p>最关键的一个写法决策——两个回调的上下文分界：</p>    回调 调用上下文 适用     <code>brightness_set</code> 原子上下文（可能从定时器/软中断路径调用） GPIO/MMIO 写寄存器这类不睡眠的操作   <code>brightness_set_blocking</code> 进程上下文（框架内部经 workqueue 转一道） I2C/SPI 芯片——会睡眠的硬件访问    <p>I2C LED 芯片错挂 <code>brightness_set</code> 是经典事故：heartbeat trigger 由定时器驱动，每次心跳都在原子上下文调你的回调——<code>i2c_smbus_write_byte_data</code> 一睡眠，"scheduling while atomic" 立刻现身。硬件访问会睡眠就挂 blocking 版，这一条不出错，LED 驱动就没什么可错的了。</p>

背光：与显示栈的关系 [I] <p>背光有独立框架（<code>backlight_device</code>），因为它天然属于显示链路而非状态指示：</p> <pre><code>/* 零代码路径：pwm-backlight */
backlight {
    compatible = "pwm-backlight";
    pwms = &lt;&amp;pwm1 0 50000&gt;;
    brightness-levels = &lt;0 64 128 192 255&gt;;   /* 非线性亮度表 */
    default-brightness-level = &lt;3&gt;;
    power-supply = &lt;&amp;vcc_bl&gt;;
};
/* 显示节点引用：panel/drm 侧 enable 时自动带起背光 */
&amp;dsi_panel { backlight = &lt;&amp;backlight&gt;; };
</code></pre> <p>背光与显示栈的联动（panel prepare → backlight enable 的时序、DRM 侧的属性暴露）属于显示专题，链 G.1/G.2；专用背光芯片（I2C 调光、电流槽配置）才需要自写 <code>backlight_ops</code>（<code>update_status</code>/<code>get_brightness</code>）驱动，骨架与 led_classdev 同构。</p>

RTC：注册一张时间表 [I] <p>RTC 框架同样接管全部文件接口（<code>/dev/rtcN</code>、<code>/sys/class/rtc/rtcN/</code>、alarm 中断分发），驱动只填"读写时间、读写闹钟"几个回调：</p> <pre><code>#include &lt;linux/rtc.h&gt;

static int myrtc_read_time(struct device *dev, struct rtc_time *tm)
{
    struct myrtc_data *data = dev_get_drvdata(dev);
    u8 regs[7];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(data-&gt;client, 0x00, 7, regs);
    if (ret &lt; 0)
        return ret;

    tm-&gt;tm_sec  = bcd2bin(regs[0] &amp; 0x7f);
    tm-&gt;tm_min  = bcd2bin(regs[1] &amp; 0x7f);
    tm-&gt;tm_hour = bcd2bin(regs[2] &amp; 0x3f);
    tm-&gt;tm_mday = bcd2bin(regs[4] &amp; 0x3f);
    tm-&gt;tm_mon  = bcd2bin(regs[5] &amp; 0x1f) - 1;    /* tm_mon 从 0 起 */
    tm-&gt;tm_year = bcd2bin(regs[6]) + 100;         /* 芯片基准 2000 年 */
    return 0;
}

static int myrtc_set_time(struct device *dev, struct rtc_time *tm)
{
    struct myrtc_data *data = dev_get_drvdata(dev);
    u8 regs[7];

    regs[0] = bin2bcd(tm-&gt;tm_sec);
    regs[1] = bin2bcd(tm-&gt;tm_min);
    regs[2] = bin2bcd(tm-&gt;tm_hour);
    regs[4] = bin2bcd(tm-&gt;tm_mday);
    regs[5] = bin2bcd(tm-&gt;tm_mon + 1);
    regs[6] = bin2bcd(tm-&gt;tm_year - 100);
    return i2c_smbus_write_i2c_block_data(data-&gt;client, 0x00, 7, regs);
}

static const struct rtc_class_ops myrtc_ops = {
    .read_time = myrtc_read_time,
    .set_time  = myrtc_set_time,
};

static int myrtc_probe(struct i2c_client *client)
{
    struct myrtc_data *data;
    struct rtc_device *rtc;

    data = devm_kzalloc(&amp;client-&gt;dev, sizeof(*data), GFP_KERNEL);
    if (!data)
        return -ENOMEM;
    data-&gt;client = client;
    i2c_set_drvdata(client, data);

    rtc = devm_rtc_allocate_device(&amp;client-&gt;dev);   /* 两步注册：先分配 */
    if (IS_ERR(rtc))
        return PTR_ERR(rtc);
    data-&gt;rtc = rtc;

    rtc-&gt;ops = &amp;myrtc_ops;
    rtc-&gt;range_min = RTC_TIMESTAMP_BEGIN_2000;
    rtc-&gt;range_max = RTC_TIMESTAMP_END_2099;

    return devm_rtc_register_device(rtc);           /* 再注册，失败自动回收 */
}
</code></pre> <p>源码走读：<code>devm_rtc_allocate_device()</code> 只是分配并挂 devm 回收；真正的注册在 <code>devm_rtc_register_device()</code>（<code>drivers/rtc/class.c</code>）→ <code>rtc_device_register()</code> → <code>rtc_dev_register()</code> 建 <code>/dev/rtcN</code> 与 cdev，同时挂入 rtc_class。两步式注册的原因：旧接口 <code>rtc_device_register()</code> 无法让框架在注册前修改 range_min/max 等属性，新版把"分配"和"生效"拆开。写新驱动一律用两步式。</p> <p>闹钟与唤醒：芯片 alarm 引脚接到 SoC 的可唤醒中断时，驱动里加 <code>set_alarm</code>/<code>alarm_irq_enable</code> ops，DT 声明 <code>wakeup-source</code>，用户态就能 <code>rtcwake -m mem -s 3600</code> 让整机睡一小时后自醒——电池产品的定时唤醒就靠这条路。</p>

misc：cdev 的极简版，判据收口 [I] <p>Part 1 D.2 用 cdev 写了完整字符设备（alloc_chrdev_region → cdev_init → cdev_add → device_create 四步）。misc 把这四步压成一步：</p> <pre><code>#include &lt;linux/miscdevice.h&gt;

static const struct file_operations mymisc_fops = {
    .owner          = THIS_MODULE,
    .read           = mymisc_read,
    .write          = mymisc_write,
    .unlocked_ioctl = mymisc_ioctl,
};

static struct miscdevice mymisc_dev = {
    .minor = MISC_DYNAMIC_MINOR,    /* 动态分配次设备号 */
    .name  = "mymisc",              /* 得到 /dev/mymisc */
    .fops  = &amp;mymisc_fops,
};

/* probe 里： */
misc_register(&amp;mymisc_dev);
/* remove 里： */
misc_deregister(&amp;mymisc_dev);
</code></pre> <p>源码走读：<code>misc_register()</code>（<code>drivers/char/misc.c</code>）内部是共享主设备号 10 的一个大 cdev——所有 misc 设备共用一个字符设备号，靠次设备号分发到各自的 fops。所以 misc 省掉的正是"主设备号管理"这件事。</p> <p>选择判据（本篇的收口结论）：</p>    维度 用 misc 用 cdev     设备数量 单个杂项 一组同类设备，要主设备号归类语义   minor 需求 动态分一个就够 要自己编码 minor（如通道号、bank 号）   代码量 一步注册 四步，但可控性完整   典型 产测钩子、一次性配置口、小状态寄存器 TS502 这类多 ioctl 数据通道设备（D.2）     <p>💡 判不准时的经验：这个设备五年后会不会长出第二个节点？不会，misc；会，cdev。</p>

资源三件套：消费者写法 [E] <p>11.3.3 已定位"为什么 probe 里要这几步"，本篇给完整写法。以 TS502 接上独立时钟源与可调 LDO 为例：</p> <pre><code>static int ts502_probe(struct i2c_client *client)
{
    struct ts502_data *data;
    int ret;

    /* 1. 电源：先电后钟，硬件手册的上电时序 */
    data-&gt;vdd = devm_regulator_get(&amp;client-&gt;dev, "vdd");
    if (IS_ERR(data-&gt;vdd))
        return dev_err_probe(&amp;client-&gt;dev, PTR_ERR(data-&gt;vdd),
                             "get vdd failed\n");
    ret = regulator_enable(data-&gt;vdd);
    if (ret)
        return ret;
    msleep(5);                          /* 手册：上电 5ms 内禁通信 */

    /* 2. 时钟 */
    data-&gt;clk = devm_clk_get(&amp;client-&gt;dev, NULL);
    if (IS_ERR(data-&gt;clk)) {
        ret = PTR_ERR(data-&gt;clk);
        goto err_regulator;             /* 反向撤销，devm 只管 get 不管时序 */
    }
    ret = clk_prepare_enable(data-&gt;clk);
    if (ret)
        goto err_regulator;

    /* 3. 引脚：99% 的驱动什么都不用写——device core 在 probe 前已自动
     *    选择 DT 里的 pinctrl-0（default 状态）。只有需要运行时切状态
     *    （如休眠切 sleep 态省电）才显式调用：                         */
    data-&gt;pins_sleep = pinctrl_lookup_state(
        devm_pinctrl_get(&amp;client-&gt;dev), "sleep");
    /* ……suspend 时 pinctrl_select_state() 切换 */

    /* 4. 资源齐了才碰寄存器 */
    ret = regmap_read(data-&gt;regmap, TS502_REG_CHIP_ID, &amp;chip_id);
    /* …… */
    return 0;

err_regulator:
    regulator_disable(data-&gt;vdd);       /* 使能是运行时操作，devm 不代管 */
    return ret;
}
</code></pre> <p>四条铁律：</p> <ol> <li>顺序即手册：电 → 钟 → 复位释放 → 通信，顺序按芯片手册的上电时序，错了就是偶发不识别。</li> <li>错误路径反向撤销：<code>devm_</code> 只保证 probe 失败/设备移除时释放引用，enable 这类运行时动作要自己反向关。资源多时用 <code>devm_add_action_or_reset</code> 或挂 PM runtime 集中管理。</li> <li>-EPROBE_DEFER 是常态：时钟/电源的提供者可能还没 probe，<code>dev_err_probe()</code> 一行处理打印+延迟探测，别自己判断。</li> <li>pinctrl 大多隐身：DT 里 <code>pinctrl-0 = &lt;&amp;ts502_pins&gt;;</code> 声明后，device core 在 probe 前自动切 default 态——驱动里显式操作 pinctrl 是少数场景（休眠省电态、功能复用切换）。</li> </ol> <p>源码走读：<code>clk_prepare_enable()</code>（<code>drivers/clk/clk.c</code>）拆两步：<code>clk_prepare</code> 可睡眠（锁电压、等 PLL 锁定），<code>clk_enable</code> 原子可用（只翻门控位）——拆开的原因是时钟树里有些操作必须睡眠，而 enable 可能被中断路径调用。合并版 <code>clk_prepare_enable</code> 只适用于进程上下文。regulator 同理：<code>regulator_enable</code> 内部可能睡眠（LDO 斜升等待），中断上下文禁用。</p>

子驱动：取共享资源的两行关键代码 [M] <p>子驱动是普通 platform_driver，唯二的 MFD 特征是共享资源的取法：</p> <pre><code>static int mypwr_rtc_probe(struct platform_device *pdev)
{
    struct mypwr_rtc *rtc;
    int irq;

    /* 1. 共享 regmap：从 parent 拿，不是自己 init */
    rtc-&gt;regmap = dev_get_regmap(pdev-&gt;dev.parent, NULL);
    if (!rtc-&gt;regmap)
        return -ENODEV;

    /* 2. 虚拟中断：platform_get_irq 拿到父驱动回填的 virq */
    irq = platform_get_irq(pdev, 0);
    if (irq &lt; 0)
        return irq;
    ret = devm_request_threaded_irq(&amp;pdev-&gt;dev, irq, NULL,
                                    mypwr_rtc_irq_handler,
                                    IRQF_ONESHOT, "mypwr-rtc", rtc);
    /* ……之后走 D.14 的 RTC 注册流程，ops 里用共享 regmap 读写 */
}
</code></pre> <p>共享安全的来源：所有子设备操作的是同一个 regmap 实例，regmap 内部持锁（D.15 的 update_bits 红利在复合芯片上才真正兑现——RTC 子驱动清中断位时不会撕裂 regulator 子驱动正在写的相邻位）。这也是"子驱动绝不自己 regmap_init"的原因：各建各的 regmap 等于各建各的锁，共享总线互踩。</p> <p>整体结构图：</p> <pre><code>I2C 总线
  └── 父驱动 mypwr（i2c_driver）
        ├── regmap（共享，内部分布式锁）
        ├── regmap_irq_chip（父 IRQ ──级联──&gt; 8 个虚拟 IRQ）
        └── mfd_add_devices()
              ├── mypwr-regulator → regulator 框架 → /sys/class/regulator
              ├── mypwr-rtc      → RTC 框架      → /dev/rtc1
              ├── mypwr-adc      → IIO 框架      → /sys/bus/iio
              └── mypwr-gpio     → gpiochip      → /sys/class/gpio
</code></pre>

零代码路径：syscon + simple-mfd [I→E] <p>MMIO 复合设备（子功能都是 DT 节点、无共享中断分发需求）有一行驱动都不用写的路径：</p> <pre><code>syscon_mfd: system-controller@1c00000 {
    compatible = "vendor,soc-sysctrl", "syscon", "simple-mfd";
    reg = &lt;0x1c00000 0x1000&gt;;

    /* 子节点由 simple-mfd 自动 populate 成 platform 设备 */
    reboot: reboot@10 { compatible = "vendor,soc-reboot"; };
};
</code></pre> <p>三个 compatible 的分工：<code>syscon</code> 让该区域成为共享 regmap 提供者（其他驱动 <code>syscon_regmap_lookup_by_phandle</code> 取用）；<code>simple-mfd</code> 让 device core 把子节点自动注册为 platform 设备。SoC 系统控制器、时钟复位混合区块大量用这个组合。I2C 复合芯片用不了 simple-mfd（子设备不在 DT 里、需要中断级联），才需要本篇的完整写法。</p>

i2c-dev / spidev：零内核代码 [I] <p>11.1.6 已给 i2c-dev 的最小例，这里补齐工程用法。i2c-dev 为每条已注册的 I2C 适配器自动生成 <code>/dev/i2c-N</code>（无需 DT 声明，适配器就绪即可用；spidev 才需要在 DT 里绑节点），用户态打开总线节点后按地址访问从机：</p> <pre><code>#include &lt;linux/i2c-dev.h&gt;
#include &lt;linux/i2c.h&gt;
#include &lt;sys/ioctl.h&gt;

int fd = open("/dev/i2c-1", O_RDWR);
ioctl(fd, I2C_SLAVE, 0x50);              /* 锁定从机地址 */

/* 等价于 smbus 读字节 */
__s32 v = i2c_smbus_read_byte_data(fd, 0x00);   /* TS502 CHIP_ID */

/* 组合事务（重复起始位，atomic 的两段式） */
struct i2c_msg msgs[2] = {
    { .addr = 0x50, .flags = 0,        .len = 1, .buf = &amp;reg },
    { .addr = 0x50, .flags = I2C_M_RD, .len = 2, .buf = data },
};
struct i2c_rdwr_ioctl_data xfr = { .msgs = msgs, .nmsgs = 2 };
ioctl(fd, I2C_RDWR, &amp;xfr);               /* 某些"先写寄存器地址再读"的怪芯片必须走这条 */
</code></pre> <p>spidev 同构：<code>/dev/spidevB.C</code> + <code>SPI_IOC_MESSAGE</code> ioctl 传全双工事务，片选、模式、速率都可逐次指定。</p>  <p>💡 注意身份：这两条路的本质是内核驱动照常存在（i2c 总线驱动、spi 控制器驱动一个不少），只是设备这一层不进内核。所以它们完全没有"绕过内核"的性能优势——每次事务照样走系统调用，慢且抖，换来的是零内核代码。</p>

UIO：寄存器 + 中断的用户态最小闭环 [I→E] <p>MMIO 设备（FPGA 逻辑最常见）用 UIO。内核侧只要一个"壳"驱动——不解析任何寄存器语义，只做三件事：声明寄存器窗口、声明中断、注册 uio_device：</p> <pre><code>#include &lt;linux/uio_driver.h&gt;
#include &lt;linux/platform_device.h&gt;

static irqreturn_t myfpga_irq(int irq, struct uio_info *info)
{
    /* 关中断或清中断源，防止用户态没来得及处理时中断风暴 */
    writel(0x1, info-&gt;mem[0].internal_addr + 0x0C);   /* 清 INT_STAT */
    return IRQ_HANDLED;
}

static int myfpga_probe(struct platform_device *pdev)
{
    struct uio_info *info;
    struct resource *res;

    info = devm_kzalloc(&amp;pdev-&gt;dev, sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    info-&gt;mem[0].name = "myfpga_regs";
    info-&gt;mem[0].addr = res-&gt;start;
    info-&gt;mem[0].size = resource_size(res);
    info-&gt;mem[0].memtype = UIO_MEM_PHYS;
    info-&gt;mem[0].internal_addr = devm_ioremap_resource(&amp;pdev-&gt;dev, res); /* 仅内核侧清中断用 */

    info-&gt;name = "myfpga";
    info-&gt;version = "1.0";
    info-&gt;irq = platform_get_irq(pdev, 0);
    info-&gt;irq_flags = IRQF_TRIGGER_RISING;
    info-&gt;handler = myfpga_irq;

    return devm_uio_register_device(&amp;pdev-&gt;dev, info);
}
</code></pre> <p>用户态侧（C 或 Python 均可）：</p> <pre><code>int fd = open("/dev/uio0", O_RDWR | O_SYNC);
void *regs = mmap(NULL, 0x1000, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
volatile uint32_t *reg = regs;

reg[0x00/4] = 0x1;              /* 写 CTRL 使能 */
while (1) {
    uint32_t irq_count;
    read(fd, &amp;irq_count, 4);    /* 阻塞等中断；返回累计中断次数 */
    process(reg[0x04/4]);       /* 处理数据 */
    reg[0x08/4] = 0x1;          /* 重新使能中断（若内核侧关了） */
}
</code></pre> <p>UIO 的语义契约就两条，写对即全对：</p> <ol> <li>read/poll 收中断：每次中断计数加一，<code>read</code> 读出 4 字节累计值；<code>poll</code>/<code>epoll</code> 可接入业务事件循环（D.3 的等待模型在用户态的原样复刻）。</li> <li>内核 handler 只负责"按住"中断：真正的中断处理逻辑全在用户态。handler 必须清中断源或关中断，否则电平触发的中断会卡死系统。</li> </ol>  <p>💡 更零代码的形态：设备简单到中断都不要时，DT 里 <code>compatible = "generic-uio";</code>（内核开 CONFIG_UIO_PDRV_GENIRQ）连壳驱动都省了——UIO 通用驱动直接接管 DT 节点的 reg 和 interrupts。</p>

注册胶水：module_platform_driver 展开 [I] <p><code>module_platform_driver()</code> 是三个宏的打包（<code>module_driver</code> 的实例化）：</p> <pre><code>/* include/linux/platform_device.h */
#define module_platform_driver(__platform_driver) \
    module_driver(__platform_driver, platform_driver_register, \
                  platform_driver_unregister)

/* include/linux/device/driver.h 展开后等价于： */
static int __init mydrv_init(void)
{
    return platform_driver_register(&amp;my_platform_driver);
}
module_init(mydrv_init);

static void __exit mydrv_exit(void)
{
    platform_driver_unregister(&amp;my_platform_driver);
}
module_exit(mydrv_exit);
</code></pre> <p>展开后看到三件事：<code>module_init</code> 标记的函数在 insmod（或内建驱动的 initcall）时执行；<code>platform_driver_register()</code> 把驱动挂到 platform 总线的驱动链表上（注册之后的匹配流程见 11.3.2）；<code>__init</code>/<code>__exit</code> 是段属性标记，内建驱动初始化完后 <code>__init</code> 段内存被回收。</p> <p>I2C 驱动的对应宏是 <code>module_i2c_driver()</code>，展开结构一模一样。胶水层没有可发挥的空间，照抄即可——骨架的功夫全在 probe/remove 里。</p>  <p>💡 <code>platform_driver_register()</code> 的调用链（<code>drivers/base/platform.c</code> → <code>driver_register()</code> → <code>bus_add_driver()</code> → 遍历设备链表触发 <code>really_probe()</code>）是 11.2/11.3 的内容，写法篇只需记住一个事实：register 返回时 probe 可能已经跑完了，所以 probe 里用到的数据必须在 register 之前就初始化好（静态结构、常量表），不能指望"register 之后再准备"。</p>

TS502 空骨架：能编译、能加载、probe 真的会跑 [I] <p>TS502 是 I2C 设备，胶水用 <code>module_i2c_driver</code>。空骨架只做一件事：probe 里读 CHIP_ID，确认芯片在场——这是所有真实驱动 probe 的第一个动作，也是本篇结束时 TS502 驱动具备的全部能力。</p> <pre><code>// SPDX-License-Identifier: GPL-2.0
/* ts502.c —— D.1 空骨架：probe 读 CHIP_ID 确认芯片在场 */
#include &lt;linux/module.h&gt;
#include &lt;linux/i2c.h&gt;
#include &lt;linux/delay.h&gt;

#define TS502_REG_CHIP_ID   0x00
#define TS502_CHIP_ID       0x50

struct ts502_data {
    struct i2c_client *client;
    /* D.2 起逐篇添加：cdev、waitqueue、kfifo、timer…… */
};

static int ts502_probe(struct i2c_client *client)
{
    struct ts502_data *data;
    int id;

    msleep(5);                  /* 手册上电时序：VDD 稳定后 5ms 内禁通信 */

    /* 第一个动作永远是"验明正身"：读 CHIP_ID */
    id = i2c_smbus_read_byte_data(client, TS502_REG_CHIP_ID);
    if (id &lt; 0)
        return dev_err_probe(&amp;client-&gt;dev, id, "read CHIP_ID failed\n");
    if (id != TS502_CHIP_ID)
        return dev_err_probe(&amp;client-&gt;dev, -ENODEV,
                             "unexpected CHIP_ID 0x%02x\n", id);

    data = devm_kzalloc(&amp;client-&gt;dev, sizeof(*data), GFP_KERNEL);
    if (!data)
        return -ENOMEM;
    data-&gt;client = client;
    i2c_set_clientdata(client, data);

    dev_info(&amp;client-&gt;dev, "TS502 probed (CHIP_ID 0x%02x)\n", id);
    return 0;
}

static void ts502_remove(struct i2c_client *client)
{
    /* 本篇 devm 托管了全部资源，remove 暂时无事可做 */
    dev_info(&amp;client-&gt;dev, "TS502 removed\n");
}

static const struct of_device_id ts502_of_match[] = {
    { .compatible = "virtual,ts502" },
    { }
};
MODULE_DEVICE_TABLE(of, ts502_of_match);

static const struct i2c_device_id ts502_id[] = {
    { "ts502", 0 },
    { }
};
MODULE_DEVICE_TABLE(i2c, ts502_id);

static struct i2c_driver ts502_driver = {
    .driver = {
        .name = "ts502",
        .of_match_table = ts502_of_match,
    },
    .probe  = ts502_probe,
    .remove = ts502_remove,
    .id_table = ts502_id,
};
module_i2c_driver(ts502_driver);

MODULE_DESCRIPTION("TS502 composite sensor driver (skeleton)");
MODULE_AUTHOR("D.1 example");
MODULE_LICENSE("GPL");
</code></pre> <p>配套设备树片段（D.7 会展开讲，本篇只需能匹配上）：</p> <pre><code>&amp;i2c1 {
    ts502@48 {
        compatible = "virtual,ts502";
        reg = &lt;0x48&gt;;
    };
};
</code></pre> <p>编译、加载、验证（在板子上，模块方式）：</p> <pre><code>make -C /lib/modules/$(uname -r)/build M=$PWD modules
insmod ts502.ko
dmesg | tail -2
[ 1234.567890] i2c 1-0048: TS502 probed (CHIP_ID 0x50)
</code></pre> <p><code>dev_err_probe()</code> 在 11.3.3 已经讲过语义：打印 + 返回错误码一体，<code>-EPROBE_DEFER</code> 时降级记录到 devices_deferred。骨架里所有错误返回统一用它，不写裸 <code>dev_err + return</code> 组合。</p>

多实例与私有数据 [I] <p>同型号芯片挂两颗（比如 I2C 总线上 0x48 和 0x49 各一颗 TS502），probe 会跑两次，每次的 <code>client</code> 不同。驱动代码里禁止用全局变量存设备状态——全局变量意味着两颗芯片互相覆盖。正确做法是每实例一份私有数据：</p> <pre><code>/* probe 里：分配并挂到 device 上 */
data = devm_kzalloc(&amp;client-&gt;dev, sizeof(*data), GFP_KERNEL);
data-&gt;client = client;
i2c_set_clientdata(client, data);        /* platform 侧是 dev_set_drvdata */

/* 其他回调里（remove、中断 handler、fops）取回来 */
struct ts502_data *data = i2c_get_clientdata(client);
</code></pre> <p><code>dev_set_drvdata</code>/<code>i2c_set_clientdata</code> 的本质是把指针塞进 <code>struct device</code> 的 <code>driver_data</code> 字段，内核在任何能拿到 <code>device</code> 的地方都能取回这份私有数据。</p>

TS502 的拼图：长出 /dev/ts502-0 [I] <p>在 D.1 骨架基础上，本篇给 <code>ts502_data</code> 加三个成员，probe 尾部加四步：</p> <pre><code>struct ts502_data {
    struct i2c_client *client;
    struct cdev cdev;           /* D.2 新增 */
    int minor;                  /* D.2 新增：ida 分配的实例编号 */
    struct mutex lock;          /* D.2 新增：保护寄存器配置序列 */
};

static DEFINE_IDA(ts502_ida);
static dev_t ts502_devt;                 /* 驱动级唯一：主设备号 */
static struct class *ts502_class;

/* probe 尾部（CHIP_ID 验证与 devm_kzalloc 之后）追加： */
    mutex_init(&amp;data-&gt;lock);

    data-&gt;minor = ida_alloc(&amp;ts502_ida, GFP_KERNEL);
    if (data-&gt;minor &lt; 0)
        return data-&gt;minor;

    cdev_init(&amp;data-&gt;cdev, &amp;ts502_fops);
    data-&gt;cdev.owner = THIS_MODULE;
    ret = cdev_add(&amp;data-&gt;cdev, MKDEV(MAJOR(ts502_devt), data-&gt;minor), 1);
    if (ret)
        goto err_ida;

    if (IS_ERR(device_create(ts502_class, &amp;client-&gt;dev,
                             MKDEV(MAJOR(ts502_devt), data-&gt;minor),
                             NULL, "ts502-%d", data-&gt;minor))) {
        ret = -ENODEV;
        goto err_cdev;
    }
    return 0;

err_cdev:
    cdev_del(&amp;data-&gt;cdev);
err_ida:
    ida_free(&amp;ts502_ida, data-&gt;minor);
    return ret;
</code></pre> <p>remove 里按逆序对称回收（D.1 的对称释放原则在这里第一次真正用上）：</p> <pre><code>static void ts502_remove(struct i2c_client *client)
{
    struct ts502_data *data = i2c_get_clientdata(client);

    device_destroy(ts502_class, MKDEV(MAJOR(ts502_devt), data-&gt;minor));
    cdev_del(&amp;data-&gt;cdev);
    ida_free(&amp;ts502_ida, data-&gt;minor);
}
</code></pre> <p>模块入口注册一次主设备号（<code>alloc_chrdev_region</code> 三层 API 的细节见 12.1.4）：</p> <pre><code>static int __init ts502_init(void)
{
    int ret = alloc_chrdev_region(&amp;ts502_devt, 0, 8, "ts502");
    if (ret)
        return ret;
    ts502_class = class_create("ts502");
    if (IS_ERR(ts502_class)) {
        unregister_chrdev_region(ts502_devt, 8);
        return PTR_ERR(ts502_class);
    }
    return i2c_add_driver(&amp;ts502_driver);
}
</code></pre>  <p>💡 这三步（ida/cdev/device_create）不能用 <code>devm_kzalloc</code> 式的托管一笔带过：它们不是"申请资源"而是"对外发布接口"，发布就必须有明确的撤销动作。产品驱动里常用 <code>devm_add_action_or_reset()</code> 把撤销动作挂进 devm 链，保持 remove 为空的目标状态（D.1 的取舍结论）。</p>  <p>加载后验证：</p> <pre><code>insmod ts502.ko
ls -l /dev/ts502-0
crw------- 1 root root 244, 0 ... /dev/ts502-0
</code></pre>

read 的三类实战边界 [I→E] <p>TS502 的 read 语义定为：一次 read 返回一帧温度（2 字节，TEMP_H/TEMP_L 原始格式）。实现只有十几行，但三处边界一处都不能错：</p> <pre><code>static ssize_t ts502_read(struct file *filp, char __user *buf,
                          size_t count, loff_t *ppos)
{
    struct ts502_data *data = filp-&gt;private_data;
    u8 frame[2];
    int ret;

    if (*ppos &gt; 0)
        return 0;                       /* 只有一帧，重读返回 EOF */

    if (count &lt; sizeof(frame))
        return -EINVAL;                 /* 缓冲区放不下完整一帧 */

    ret = i2c_smbus_read_i2c_block_data(data-&gt;client, TS502_REG_TEMP_H,
                                        sizeof(frame), frame);
    if (ret &lt; 0)
        return ret;                     /* I2C 错误原样上传 */

    if (copy_to_user(buf, frame, sizeof(frame)))
        return -EFAULT;

    *ppos += sizeof(frame);
    return sizeof(frame);
}
</code></pre>

问题：轮询的代价 [I] <p>D.2 的 read 是"有一帧给一帧"。业务要持续采温度，只能这样：</p> <pre><code>while (1) {
    n = read(fd, buf, 2);        /* 没数据也立即返回 */
    if (n &gt; 0)
        handle(buf);
    usleep(10000);               /* 睡 10ms 再试 */
}
</code></pre> <p><code>usleep</code> 的数字怎么拍都是错的：睡长了，数据就绪到被读取之间的延迟白白增加；睡短了，空转烧 CPU。这是驱动没提供通知机制时业务的唯一出路。正确结构是反过来——业务睡到条件满足，驱动在条件满足时叫醒它。内核提供三条通道，适用面不同：</p>    机制 业务侧 适用场景     阻塞 read read 自然挂起 单设备、顺序消费，最简单的业务模型   poll/epoll epoll_wait 多路复用 同时盯多个 fd 的业务（主流服务器式写法）   fasync SIGIO 信号回调 简单事件通知，不需要读数据的场合    <p>三条通道在驱动侧共用一个地基：wait_queue。本篇逐层搭上去。</p>

poll：接入 epoll 业务模型 [E] <p>业务的现代写法是 epoll 同时盯几十个 fd（串口、socket、设备节点混在一个 epoll 集合里）。驱动侧只需实现一个 <code>fops-&gt;poll</code>：</p> <pre><code>static __poll_t ts502_poll(struct file *filp, poll_table *wait)
{
    struct ts502_data *data = filp-&gt;private_data;
    __poll_t mask = 0;

    poll_wait(filp, &amp;data-&gt;wq, wait);          /* 把本 fd 挂到等待队列 */

    if (READ_ONCE(data-&gt;fifo_ready))
        mask |= EPOLLIN | EPOLLRDNORM;         /* 当前可读就置位 */

    return mask;
}
</code></pre> <p>两个动作缺一不可：<code>poll_wait</code> 登记（让 wake_up 能叫醒 epoll_wait 里的业务），返回掩码报告当前状态。内核侧 do_poll 怎么轮询、怎么睡眠见 12.1.4，驱动侧不需要关心。</p>

fasync：SIGIO 信号通道 [I→E] <p>第三条通道最老也最简单：业务 <code>fcntl(fd, F_SETFL, O_ASYNC)</code> 之后，数据就绪时驱动发 SIGIO，业务在信号 handler 里收到通知。驱动侧三件套：</p> <pre><code>static int ts502_fasync(int fd, struct file *filp, int on)
{
    struct ts502_data *data = filp-&gt;private_data;

    return fasync_helper(fd, filp, on, &amp;data-&gt;fasync);
}

static int ts502_release(struct inode *inode, struct file *filp)
{
    ts502_fasync(-1, filp, 0);      /* 注销本 fd 的异步通知，防野信号 */
    return 0;
}

/* fops 里挂 .fasync = ts502_fasync */
/* 数据就绪时（见 ts502_data_arrived 第③步）：kill_fasync(&amp;data-&gt;fasync, SIGIO, POLL_IN) */
</code></pre> <p>release 里那句 <code>ts502_fasync(-1, filp, 0)</code> 不能省：fd 关了但 fasync 链表里还挂着，kill_fasync 会向已关闭的 filp 发信号，轻则警告重则 use-after-free。</p>

INT 脚接入：设备树声明 [E] <p>TS502 手册写明 INT 引脚开漏输出、低电平有效——这一行硬件事实直接决定设备树怎么写：</p> <pre><code>&amp;i2c1 {
    ts502@48 {
        compatible = "virtual,ts502";
        reg = &lt;0x48&gt;;
        interrupt-parent = &lt;&amp;gpio1&gt;;
        interrupts = &lt;5 IRQ_TYPE_LEVEL_LOW&gt;;   /* GPIO1_5，低电平触发 */
    };
};
</code></pre>

handler 写法：线程化中断的驱动侧 [E] <p>两阶段模型（顶半部 + irq_thread）的机制见 10.4.2，这里只给驱动侧的完整写法：</p> <pre><code>#define TS502_INT_DATA_READY  0x01
#define TS502_INT_FIFO_HALF   0x02

/* 线程 handler：在进程上下文跑，可以睡眠，可以做 I2C */
static irqreturn_t ts502_irq_thread(int irq, void *dev_id)
{
    struct ts502_data *data = dev_id;
    int status;

    /* ① 读中断状态：TS502 的 INT_STATUS 是 RW1C */
    status = i2c_smbus_read_byte_data(data-&gt;client, TS502_REG_INT_STATUS);
    if (status &lt; 0)
        return IRQ_HANDLED;             /* I2C 错误：别再触发风暴，认下这次 */

    if (!(status &amp; (TS502_INT_DATA_READY | TS502_INT_FIFO_HALF)))
        return IRQ_NONE;                /* 假中断：不是我们的（共享线下必须判） */

    /* ② 清中断源：写 1 清零对应位，INT 脚弹回高电平 */
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_INT_STATUS, status);

    /* ③ 按位分发 */
    if (status &amp; TS502_INT_DATA_READY)
        ts502_data_arrived(data);       /* D.3 的三动作整体搬到这里 */
    if (status &amp; TS502_INT_FIFO_HALF)
        schedule_work(&amp;data-&gt;fifo_work);/* 批量搬运丢给 workqueue（D.6 展开） */

    return IRQ_HANDLED;
}

/* probe 里注册 */
    ret = devm_request_threaded_irq(&amp;client-&gt;dev, client-&gt;irq,
                                    NULL,                  /* 顶半部用内核默认 */
                                    ts502_irq_thread,
                                    IRQF_ONESHOT,
                                    "ts502", data);
    if (ret)
        return dev_err_probe(&amp;client-&gt;dev, ret, "request IRQ %d failed\n",
                             client-&gt;irq);

    /* 开中断：允许数据就绪从 INT 脚输出 */
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_INT_MASK,
                              TS502_INT_DATA_READY | TS502_INT_FIFO_HALF);
</code></pre> <p>三个写法要点：</p> <ol> <li>顶半部传 NULL：内核装一个默认顶半部，直接返回 IRQ_WAKE_THREAD（10.4.2 的 handler NULL 简化模式）。I2C 器件的中断处理必须读写寄存器、必须睡眠，顶半部本来就无事可做——这是 I2C/SPI 设备驱动的标准形态</li> <li>IRQF_ONESHOT：电平触发 + 线程化的必配标志。它让中断线在线程 handler 跑完之前保持屏蔽——否则清源前的低电平会让中断控制器不断重新触发，线程还没清完源就被新中断淹没</li> <li>清中断源（②）在分发（③）之前：RW1C 写完、INT 脚弹回，这段时间窗口内到达的新事件会体现在下一次 INT_STATUS 读取里。先分发后清源的写法，会把分发期间到达的事件一并清掉——丢事件的第一根因</li> </ol>

销毁纪律：remove 里的顺序 [E] <p>定时器与 workqueue 都是异步回调——remove 返回后回调还可能被触发，访问已释放的 <code>ts502_data</code> 就是 use-after-free（rmmod 后随机 oops 的经典根因）。销毁必须"sync"，且顺序固定：</p> <pre><code>static void ts502_remove(struct i2c_client *client)
{
    struct ts502_data *data = i2c_get_clientdata(client);

    hrtimer_cancel(&amp;data-&gt;poll_timer);      /* ① 先停触发源：等正在跑的回调结束 */
    cancel_work_sync(&amp;data-&gt;poll_work);     /* ② 再停下游：等正在跑的 work 结束 */
    /* …… 之后才能安全释放 cdev/ida 等资源 …… */
}
</code></pre> <p>三个细节：</p> <ul> <li>顺序不能反：先 cancel_work 后 hrtimer_cancel，中间窗口里定时器回调还能 <code>schedule_work</code> 把 work 重新排上——先掐触发源，再收下游</li> <li>timer_list 对应 <code>del_timer_sync</code>（新内核别名 <code>timer_delete_sync</code>）：等正在执行的回调返回才返回。普通 <code>del_timer</code> 不等待，remove 里禁用</li> <li>sync 版不能在回调自身里调用：回调里 <code>del_timer_sync(自己)</code> 是死锁——回调要等自己结束。回调内部只能"不再 rearm"，销毁动作永远在外部上下文做</li> </ul> <p>devm 党也逃不过这条：<code>devm_kzalloc</code> 的释放发生在 remove 之后，而 hrtimer/work 的 sync 取消必须在 remove 之中完成——托管内存不代表托管回调的生命周期。</p>

kfifo：TS502 的批量缓冲落地 [E] <p>内核自带的环形缓冲 <code>kfifo</code>（<code>linux/kfifo.h</code>）是驱动里生产者-消费者缓冲的默认答案。TS502 的数据通路：work（生产者，批量读芯片 FIFO）→ kfifo → read（消费者，弹给用户态）。</p> <pre><code>#include &lt;linux/kfifo.h&gt;

struct ts502_data {
    /* …… */
    struct kfifo fifo;              /* 采样数据环形缓冲 */
    struct work_struct fifo_work;   /* D.4 埋的 FIFO 半满批量搬运 */
};

/* probe 里：4KB 缓冲 = 2048 个采样点 */
ret = kfifo_alloc(&amp;data-&gt;fifo, 4096, GFP_KERNEL);

/* 生产者：FIFO 半满中断转来的 work（进程上下文，可以做 I2C） */
static void ts502_fifo_work(struct work_struct *work)
{
    struct ts502_data *data = container_of(work, struct ts502_data, fifo_work);
    u8 burst[32];                       /* 一次最多搬 16 帧 × 2 字节 */
    int ret, depth;

    depth = i2c_smbus_read_byte_data(data-&gt;client, TS502_REG_FIFO_STATUS);
    if (depth &lt; 0 || !(depth &amp; 0x3f))
        return;

    ret = i2c_smbus_read_i2c_block_data(data-&gt;client, TS502_REG_FIFO_DATA,
                                        sizeof(burst), burst);
    if (ret &lt; 0)
        return;

    kfifo_in(&amp;data-&gt;fifo, burst, ret);  /* 入环：满时返回实际入队字节数 */

    if (kfifo_len(&amp;data-&gt;fifo) &gt;= 2)
        ts502_data_arrived(data);       /* 复用 D.3 通知：置标志+唤醒+SIGIO */
}

/* 消费者：read 改为从 kfifo 弹出（kfifo_to_user 内部做好 copy_to_user） */
static ssize_t ts502_read(struct file *filp, char __user *buf,
                          size_t count, loff_t *ppos)
{
    struct ts502_data *data = filp-&gt;private_data;
    unsigned int copied;
    int ret;

    /* …… D.3 的阻塞/非阻塞等待逻辑不变 …… */

    ret = kfifo_to_user(&amp;data-&gt;fifo, buf, count &amp; ~1UL, &amp;copied);
    return ret ? ret : copied;
}
</code></pre> <p>kfifo 的三个关键性质：</p> <ol> <li>单生产者单消费者无锁：<code>kfifo_in</code> 与 <code>kfifo_out</code> 内部用内存屏障配对，一写一读不需要外加锁——中断转 work、work 到 read 这条链正好满足。多生产者（两个 work 同时 in）必须上锁或用 <code>kfifo_in_locked</code></li> <li>满了丢新数据：<code>kfifo_in</code> 返回实际入队字节数，写满时静默截断。采集场景要明确溢出策略：丢新的（保留历史）还是丢旧的（<code>kfifo_skip</code> 腾位置），并在 FIFO_STATUS 溢出位置位时上报统计（D.9 的 debugfs 计数器）</li> <li><code>kfifo_to_user</code> 直达用户态：省一次内核内存到内核内存的拷贝，比"先 kfifo_out 到临时缓冲再 copy_to_user"少一轮</li> </ol>

mmap 直通：野路子的正统形态 [E→M] <p>需求本身正当：用户态想直接读硬件寄存器（调试工具）、想要零拷贝的数据通路（高吞吐采集）。野路子有两张面孔——<code>/dev/mem</code> 映整个物理内存（11.1.4 展示过，等于把系统大门钥匙交给所有进程）、驱动里 ioremap 后自己维护一套 ad-hoc 接口。正统形态是驱动实现 mmap fop，把映射范围收在自己的校验之下：</p> <pre><code>static int ts502_mmap(struct file *filp, struct vm_area_struct *vma)
{
    size_t size = vma-&gt;vm_end - vma-&gt;vm_start;

    /* ① 校验：只允许映射自己的资源窗口，offset 与 size 双重检查 */
    if (vma-&gt;vm_pgoff != 0 || size &gt; TS502_WINDOW_SIZE)
        return -EINVAL;

    /* ② 寄存器窗口必须禁 cache */
    vma-&gt;vm_page_prot = pgprot_noncached(vma-&gt;vm_page_prot);

    /* ③ 物理帧号映射进用户地址空间 */
    if (remap_pfn_range(vma, vma-&gt;vm_start,
                        data-&gt;regs_phys &gt;&gt; PAGE_SHIFT,
                        size, vma-&gt;vm_page_prot))
        return -EAGAIN;
    return 0;
}
</code></pre> <p>四种正统形态按需求选：</p>    需求 形态 关键 API     用户态访问设备寄存器（调试/产测） 寄存器窗口映射 <code>remap_pfn_range</code> + <code>pgprot_noncached</code>   零拷贝数据通路（采集→用户态） coherent 缓冲直通 <code>dma_mmap_coherent</code>   大块预留内存（帧缓冲/AI 推理输入） reserved-memory 声明 + 映射 设备树 reserved-memory + <code>remap_pfn_range</code>   快速原型、硬件未定型 放弃内核 mmap，用 UIO D.17 用户态驱动    <p>安全边界三条：校验 <code>vm_pgoff</code> 与 size（不校验等于把任意物理内存拱手让人，/dev/mem 的洞换个地方重现）；寄存器窗口禁 cache（不禁则用户态读到的是 cache 旧值）；只映射自己的资源（<code>data-&gt;regs_phys</code> 来自自己的 DT reg，绝不接受用户传入物理地址）。配套语义：mmap 设备的 <code>.llseek</code> 用 <code>fixed_size_llseek</code>（D.2 的四种取值在这里闭环）。</p>

TS502：硬件事实全部进 DT [E] <pre><code>&amp;i2c1 {
    ts502@48 {
        compatible = "virtual,ts502";
        reg = &lt;0x48&gt;;                          /* I2C 地址 */
        interrupt-parent = &lt;&amp;gpio1&gt;;
        interrupts = &lt;5 IRQ_TYPE_LEVEL_LOW&gt;;   /* INT 脚接线与触发形态 */
        virtual,alarm-threshold = &lt;85&gt;;        /* 报警阈值 °C */
        virtual,default-sample-rate = &lt;2&gt;;     /* 默认采样率档位 */
        virtual,no-irq;                        /* 本板 INT 未接线：走轮询后备 */
        wakeup-source;                         /* 可作系统唤醒源（D.8 用） */
    };
};
</code></pre> <p>probe 里的读取（有默认值的一律"读不到就用默认"，必选属性读不到直接失败）：</p> <pre><code>struct device_node *np = client-&gt;dev.of_node;
u32 val;

/* 可选属性：读不到用默认值 */
if (!of_property_read_u32(np, "virtual,alarm-threshold", &amp;val))
    data-&gt;alarm = val;
else
    data-&gt;alarm = 90;                        /* 手册默认阈值 */

if (!of_property_read_u32(np, "virtual,default-sample-rate", &amp;val) &amp;&amp; val &lt;= 2)
    data-&gt;sample_rate = val;
else
    data-&gt;sample_rate = 1;

/* 三态开关：属性存在 = 本板没接 INT 脚 */
data-&gt;int_connected = !of_property_read_bool(np, "virtual,no-irq") &amp;&amp;
                      client-&gt;irq &gt; 0;
</code></pre> <p>读完立即用：<code>virtual,alarm-threshold</code> 写进 PWM_ALARM 寄存器，<code>default-sample-rate</code> 写进 CTRL——DT 是配置的源头，寄存器是配置的落点，驱动里没有第三处真相。</p>

suspend/resume 回调实现 [E] <pre><code>static int ts502_suspend(struct device *dev)
{
    struct ts502_data *data = dev_get_drvdata(dev);

    mutex_lock(&amp;data-&gt;lock);

    /* ① 保存会丢失的寄存器上下文（片内 RAM 掉电即失） */
    data-&gt;saved_ctrl = i2c_smbus_read_byte_data(data-&gt;client, TS502_REG_CTRL);
    data-&gt;saved_int_mask = i2c_smbus_read_byte_data(data-&gt;client, TS502_REG_INT_MASK);
    data-&gt;saved_alarm = i2c_smbus_read_byte_data(data-&gt;client, TS502_REG_PWM_ALARM);

    /* ② 停业务：关采样使能（bit0 清零），保留阈值等静态配置 */
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_CTRL,
                              data-&gt;saved_ctrl &amp; ~0x01);

    /* ③ 唤醒源处理：声明了 wakeup-source 的板子，把 IRQ 转唤醒模式 */
    if (device_may_wakeup(dev))
        enable_irq_wake(data-&gt;client-&gt;irq);

    mutex_unlock(&amp;data-&gt;lock);
    return 0;
}

static int ts502_resume(struct device *dev)
{
    struct ts502_data *data = dev_get_drvdata(dev);

    mutex_lock(&amp;data-&gt;lock);

    if (device_may_wakeup(dev))
        disable_irq_wake(data-&gt;client-&gt;irq);   /* 与 suspend 严格对称 */

    /* ① 恢复寄存器上下文（顺序：先静态配置，后使能采样） */
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_INT_MASK, data-&gt;saved_int_mask);
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_PWM_ALARM, data-&gt;saved_alarm);
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_CTRL, data-&gt;saved_ctrl);

    /* ② 清一遍残留中断状态，避免 suspend 期间的积压事件误触发 */
    i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_INT_STATUS, 0xff);

    mutex_unlock(&amp;data-&gt;lock);
    return 0;
}

static DEFINE_SIMPLE_DEV_PM_OPS(ts502_pm_ops, ts502_suspend, ts502_resume);

static struct i2c_driver ts502_driver = {
    .driver = {
        .name = "ts502",
        .of_match_table = ts502_of_match,
        .pm = pm_sleep_ptr(&amp;ts502_pm_ops),   /* 未开 CONFIG_PM_SLEEP 时编译为空 */
    },
    /* …… */
};
</code></pre> <p>三个写法要点：</p> <ol> <li>suspend 顺序是"先保存、再停机"——先读出会丢的寄存器，再关采样。顺序反了，保存的就是停机后的状态</li> <li>resume 顺序是"先恢复配置、再使能"——CTRL（采样使能）最后写，恢复期间不采样</li> <li>suspend/resume 里可以做 I2C：suspend 回调在进程上下文跑（机制见 15.5），可以睡眠、可以 I2C 事务。真正的约束是父设备可能已经先睡——I2C 控制器驱动按 dpm_list 顺序在子设备之后 suspend（叶子先睡，15.1.2 的 dpm_list），所以子设备 suspend 里做 I2C 是安全的；反过来 resume 顺序父先子后，同样安全</li> </ol>

打印的艺术：dynamic debug [I→E] <p><code>printk/dev_info</code> 编译进去就永远打印，<code>#define DEBUG</code> 要重编译重部署——现场调试两个都不可用。正确姿势是 <code>dev_dbg()</code> + dynamic debug：打印语句平时零开销躺平，需要时运行时分文件、分行打开，不用重启不用重编译：</p> <pre><code>/* 代码里：按设备粒度打调试信息 */
dev_dbg(&amp;client-&gt;dev, "FIFO depth=%d, burst=%d bytes\n", depth, ret);

/* 中断/高频路径：限频版本，一秒最多一条 */
dev_dbg_ratelimited(&amp;client-&gt;dev, "spurious interrupt status=0x%02x\n", status);
</code></pre> <p>现场打开（内核配置 <code>CONFIG_DYNAMIC_DEBUG=y</code>）：</p> <pre><code>mount -t debugfs none /sys/kernel/debug
echo 'file ts502.c +p' &gt; /sys/kernel/debug/dynamic_debug/control   # 整个文件
echo 'file ts502.c line 120-135 +p' &gt; .../control                  # 精确到行
echo 'module ts502 +p' &gt; .../control                               # 整个模块
</code></pre> <p>三条打印纪律：</p> <ol> <li>按设备打，不打裸 printk：<code>dev_dbg(dev, ...)</code> 输出自带设备名（<code>i2c 1-0048</code>），多实例场景立刻知道是哪颗芯片；裸 <code>pr_debug</code> 在多实例驱动里等于没打</li> <li>高频路径必限频：中断 handler、poll 回调里的打印用 <code>xxx_ratelimited</code> 变体——中断风暴时打印本身就是风暴放大器（打印拖慢 handler，更多中断积压）</li> <li>结构化输出：状态类信息打成 <code>key=value</code> 格式（<code>depth=16 overflow=0</code>），现场 <code>dmesg | grep</code> 与日志分析脚本都能直接消费</li> </ol>

sysfs 属性：一值一属性 [I→E] <p>sysfs 是驱动的正式门面（ABI 级，写进内核文档就要维护），设计纪律只有一条：一个属性一个值，文本形式。</p> <pre><code>/* TS502：报警阈值暴露为 sysfs 读写属性 */
static ssize_t alarm_threshold_show(struct device *dev,
                                    struct device_attribute *attr, char *buf)
{
    struct ts502_data *data = dev_get_drvdata(dev);
    int val = i2c_smbus_read_byte_data(data-&gt;client, TS502_REG_PWM_ALARM);

    if (val &lt; 0)
        return val;
    return sysfs_emit(buf, "%d\n", val);      /* 一值一属性，换行结尾 */
}

static ssize_t alarm_threshold_store(struct device *dev,
                                     struct device_attribute *attr,
                                     const char *buf, size_t count)
{
    struct ts502_data *data = dev_get_drvdata(dev);
    int val, ret;

    ret = kstrtoint(buf, 0, &amp;val);
    if (ret || val &lt; 0 || val &gt; 125)          /* 手册范围校验 */
        return -EINVAL;

    ret = i2c_smbus_write_byte_data(data-&gt;client, TS502_REG_PWM_ALARM, val);
    return ret &lt; 0 ? ret : count;
}
static DEVICE_ATTR_RW(alarm_threshold);

static struct attribute *ts502_attrs[] = {
    &amp;dev_attr_alarm_threshold.attr,
    NULL,
};
ATTRIBUTE_GROUPS(ts502);

/* i2c_driver.driver.dev_groups = ts502_groups; —— 核心自动建/删属性文件 */
</code></pre> <p>效果：</p> <pre><code>cat /sys/bus/i2c/devices/1-0048/alarm_threshold
85
echo 90 &gt; /sys/bus/i2c/devices/1-0048/alarm_threshold
</code></pre> <p>与 ioctl 的选型（D.2 立过的原则在这里收口）：</p>     sysfs 属性 ioctl     数据形态 单值、文本 多字段、二进制结构体   原子性 单值天然原子 多字段一次读写天然原子   使用方 shell 脚本、运维、产测 业务程序   ABI 维护 内核文档登记，强约束 自定义，靠 size/version 自律    <p>TS502 两个都留不是冗余：阈值给运维调（sysfs），采样率+完整配置给业务调（ioctl）。同一配置两通道要同步——sysfs 改了阈值，ioctl GET_CFG 读到的必须一致（都落在寄存器这唯一真相上）。</p>

debugfs + seq_file：开发期的自由区 [E] <p>sysfs 有 ABI 纪律，多值、表格、内部状态都不适合放。这些给开发者和现场工程师的东西放 debugfs——明确定位非 ABI：内容随时可变，业务禁止依赖。</p> <pre><code>#include &lt;linux/debugfs.h&gt;
