    }
    seq_printf(s, "irq_count      = %u\n", data-&gt;irq_count);
    seq_printf(s, "overflow_count = %u\n", data-&gt;overflow_count);
    seq_printf(s, "wake_count     = %u\n", data-&gt;wake_count);
    return 0;
}
